/* ===========================================================
   ingles4/unit10.js — Inglés 4 · Unit 10: Discoveries and mistakes
   Estructura: sections[] → activities[] → { type, ...datos }
   Tipos disponibles: notes, flashcards, match, mcq, dictation,
   dialog, speaking, stress, reading, fix, soft, comment, order, roleplay
   Fuente: resúmenes oficiales Evolve (Vocabulary / Grammar /
   Functional language summary) — sin ejercicios del alumno.
   =========================================================== */
(() => {
  /* ---------- Vocabulario base ---------- */
  /* Lesson 1 · Talking about discoveries: [expresión, def ES, def EN corta, ejemplo del curso, pregunta] */
  const DS = [
    ['carry out research', 'investigar, llevar a cabo una investigación (v.): estudiar un tema a fondo para descubrir información nueva', 'to study a subject in detail in order to discover new information about it', 'My sister is a marine biologist. She and her partner are carrying out research about the effects of pollution on sea life.', '¿Sobre qué estás carrying out research en tu tesis?'],
    ['face a challenge', 'enfrentar un reto (v.): lidiar con algo difícil que pone a prueba tu capacidad o tu determinación', 'to deal with something that is difficult and that tests your ability or determination', 'We faced some challenges on our hike in Oregon. At one point we had to walk through water that was up to our chests! We managed to finish the hike, though, and it felt great.', '¿Cuál fue el último challenge que enfrentaste en el trabajo?'],
    ['gain knowledge', 'adquirir conocimientos (v.): obtener más información o comprensión sobre algo', 'to get more information about or understanding of something', 'Since I started nursing school, I have gained a lot of knowledge about the human body and how to care for people.', '¿Dónde has gained more knowledge: en la universidad o en el trabajo?'],
    ['make a breakthrough', 'lograr un avance decisivo (v.): hacer un descubrimiento o desarrollo importante que ayuda a resolver un problema', 'to make an important discovery or development that helps solve a problem', 'Medical researchers have made a breakthrough in developing a vaccine for the new virus. They believe that the discovery will lead to a successful vaccine.', '¿Recuerdas un momento en que tu equipo made a breakthrough con un bug difícil?'],
    ['make a connection', 'establecer una relación, atar cabos (v.): darse cuenta de que hay una relación entre personas o cosas', 'to realize that there is a relationship between people or things', 'Gina gave a good presentation that helped us make the connection between what different customer groups are saying. Our younger and older customers have different needs, but we can address them in a similar way.', '¿Alguna vez made a connection entre dos problemas que parecían distintos?'],
    ['make a discovery', 'hacer un descubrimiento (v.): encontrar o averiguar algo importante', 'to find (out) something important', "While I was hiking with my daughter, we made a discovery. We found a rare kind of bird that hasn't been seen before in this area.", '¿Qué discovery hiciste la última vez que revisaste código antiguo?'],
    ['notice a phenomenon', 'observar un fenómeno (v.): ver o darse cuenta de que algo existe o sucede, normalmente algo inusual', 'to see or realize that something exists or happens, usually something unusual', 'Isaac Newton noticed the phenomenon of apples falling straight down to the ground. This led him to develop the theory of gravity.', '¿Qué phenomenon has noticed en los clientes de tu negocio?'],
    ['provide insight', 'aportar una perspectiva, arrojar luz (v.): dar una comprensión nueva sobre algo', 'to give new understanding about something', 'Information from space satellites has provided insight into the environment on Mars, including the discovery of water on the planet.', '¿Qué dato te provided insight sobre tus usuarios?'],
    ['provide a solution', 'dar una solución (v.): dar una respuesta a un problema', 'to give an answer to a problem', 'There was a problem with too much litter on the streets, so the city provided a solution by adding more trash and recycling bins.', '¿Prefieres a la gente que señala problemas o a la que provides solutions?'],
  ];
  /* Lesson 2 · Discussing right and wrong */
  const RW = [
    ['blame', 'culpa (n.) / culpar (v.): responsabilidad por algo malo; decir o pensar que alguien es responsable de algo malo que pasó', 'responsibility for something bad; to say that someone is responsible for something bad', 'I got in a car accident today. The woman blamed me for the accident, but I think she made an illegal turn.', '¿Quién recibe el blame cuando falla un despliegue en tu equipo?'],
    ['blunder', 'metedura de pata, error garrafal (n.): un error grave y a menudo tonto', 'a serious and often stupid mistake', 'The company president made a pretty bad blunder during his speech when he forgot the name of the new vice president. He seemed embarrassed by his mistake.', '¿Cuál ha sido tu peor blunder en una reunión?'],
    ['confusion', 'confusión (n.): estado en que la gente no entiende qué pasa o qué debe hacer', 'a state in which people do not understand what is happening or what they should do', "The new system we're supposed to use has created a lot of confusion. No one really understands how to use it.", '¿Qué herramienta del banco crea más confusion entre los usuarios?'],
    ['correct a mistake', 'corregir un error (v.): arreglar o mejorar un error o un problema', 'to make a mistake or problem right or better', 'Timmy, do you see what you did wrong? Can you correct your mistake?', '¿Corriges tus mistakes en silencio o avisas al equipo?'],
    ['epic fail', 'fracaso épico, desastre total (n., informal): cuando algo sale completamente mal de forma vergonzosa', 'when something goes completely wrong in an embarrassing way', 'I tried to make dinner, but it was an epic fail. I burned the chicken and there was smoke everywhere.', '¿Cuál fue tu último epic fail en la cocina?'],
    ['fault', 'culpa (n.): responsabilidad por un error o por haber hecho algo mal (It was my fault)', 'responsibility for a mistake or for having done something wrong', "Oh no, I'm so sorry. That was my fault. I'll clean it up.", '¿Te cuesta decir "it was my fault"?'],
    ['fix a problem', 'arreglar, resolver un problema (v.)', 'to solve a problem', 'We fixed the problem with your password. Now you can log in.', '¿Qué problem fixed esta semana?'],
    ['get something wrong', 'equivocarse en algo (v.): dar una respuesta o un resultado que no es correcto', 'to produce an answer or result that is not correct', "I failed the test. I guess I got a lot of things wrong. I'll have to study harder next time.", '¿Qué sueles get wrong en inglés: las preposiciones, los tiempos?'],
    ['make a mistake', 'cometer un error (v.): hacer o pensar algo equivocado', 'to do or think something that is wrong', 'I think the company has made an error on my cell phone bill. It says I called China, but I never did.', '¿Cuál fue el último mistake que made en un pedido?'],
    ['make something right', 'enmendar, arreglar las cosas (v.): resolver un problema o corregir un error con alguien', 'to solve a problem or correct a mistake', "A: Oh no, I dropped the customer's salad! B: We can make it right. Can you make a new salad while I clean this up?", '¿Cómo makes it right con un cliente al que le llegó mal el pedido?'],
    ['misunderstanding', 'malentendido (n.): cuando alguien no entiende algo correctamente', "when someone doesn't understand something correctly", "A: My wife ordered an espresso with no milk. She's allergic to milk. B: Oh, I'm sorry for the misunderstanding. I thought you asked for a cappuccino. I'll get you a new one right away.", '¿Recuerdas un misunderstanding por un mensaje de Slack?'],
    ['mix-up', 'confusión, lío (n.): un error porque las cosas se mezclaron o se confundieron entre sí', 'a mistake because things are confused', "A: Excuse me, I can't find my luggage. B: I'll check the tracking information. It looks like it went to the wrong carousel by mistake. Sorry for the mix-up. You can find it at carousel 4.", '¿Has tenido un mix-up con pedidos de dos clientes el mismo día?'],
  ];
  const ALL = [...DS, ...RW];
  const findW = k => ALL.find(x => x[0] === k);

  /* situación → expresión: [frase con hueco, respuesta, clave en DS/RW, respuestas que NO sirven como distractor] */
  const SIT = [
    ['Marine biologists ___ on the effects of plastic on sea life.', 'carry out research', 'carry out research', []],
    ["Every migration is hard, but this time we ___ nobody expected: the old database had no backups.", 'face a challenge', 'face a challenge', []],
    ['You ___ faster when you teach what you learn.', 'gain knowledge', 'gain knowledge', []],
    ['Researchers hope to ___ in cancer treatment this decade.', 'make a breakthrough', 'make a breakthrough', ['make a discovery']],
    ['Reading the logs, I was able to ___ between the crash and the Friday release.', 'make a connection', 'make a connection', []],
    ['Every time I open an old folder on the server, I ___: scripts from 2012!', 'make a discovery', 'make a discovery', ['make a breakthrough']],
    ['Good scientists ___ and then ask why it happens.', 'notice a phenomenon', 'notice a phenomenon', []],
    ['The survey results ___ into why customers abandon the app.', 'provide insight', 'provide insight', ['provide a solution']],
    ["We don't need more meetings about the bug; we need someone to ___.", 'provide a solution', 'provide a solution', ['fix a problem', 'provide insight']],
    ["Don't ___ the intern for the crash. A senior developer reviewed the code.", 'blame', 'blame', ['fault']],
    ["Forgetting the CEO's name in front of everyone was a real ___.", 'blunder', 'blunder', ['epic fail']],
    ['The new timesheet system has created a lot of ___. Nobody knows which form to use.', 'confusion', 'confusion', ['misunderstanding', 'mix-up']],
    ['Please check your report and ___ before you send it to the client.', 'correct a mistake', 'correct a mistake', ['fix a problem', 'make something right']],
    ["I tried to bake a cake for my wife's birthday. It was an ___: raw inside and burned outside.", 'epic fail', 'epic fail', ['blunder']],
    ["I'm so sorry, I dropped your coffee. That was my ___.", 'fault', 'fault', ['blame']],
    ["Our job isn't to find who did it; it's to ___ before the bank opens.", 'fix a problem', 'fix a problem', ['correct a mistake', 'make something right', 'provide a solution']],
    ['If you ___ on the exam, the professor lets you explain your reasoning.', 'get something wrong', 'get something wrong', ['make a mistake']],
    ['Everybody can ___; the important thing is to admit it.', 'make a mistake', 'make a mistake', ['get something wrong']],
    ["We sent the wrong order. Let's ___: a new order, free, with a note.", 'make something right', 'make something right', ['fix a problem', 'correct a mistake']],
    ['She said Tuesday, I heard Thursday. It was a simple ___.', 'misunderstanding', 'misunderstanding', ['mix-up', 'confusion']],
    ["There was a ___ at the airport: my bag went to carousel 4 and someone else's came to me.", 'mix-up', 'mix-up', ['misunderstanding', 'confusion']],
  ];
  const SITW = SIT.map(s => s[1]);

  window.UNIT_DATA['ingles4/unit10'] = {
    source: 'Evolve · Unit 10 · Discoveries and mistakes',
    description: 'Descubrimientos y errores: el tercer condicional (<i>If I had known, I would have…</i>), los modales de probabilidad en el pasado (<i>must / might / could / couldn\'t / should have</i>), las colocaciones de la ciencia (<i>make a breakthrough, carry out research</i>), el vocabulario de la culpa y el arreglo (<i>blunder, mix-up, my fault, make it right</i>) y cómo contar una historia manteniendo el interés (<i>You won\'t believe this, but… / But that\'s not all!</i>).',
    cando: [
      "Imaginar un pasado distinto con el tercer condicional (<i>If I had checked the address, I wouldn't have gotten lost</i>) sin poner <i>would</i> después de <i>if</i>",
      "Deducir, suponer y criticar el pasado: <i>must have</i> (seguro), <i>might / may have</i> (quizá), <i>couldn't have</i> (imposible), <i>should have</i> (crítica)",
      "Hablar de ciencia y aprendizaje con colocaciones: <i>carry out research, make a breakthrough, notice a phenomenon, provide insight</i>",
      "Reconocer un error y arreglarlo: <i>It was my fault · a mix-up · a misunderstanding · We'll make it right</i>, sin culpar a otros",
      "Contar una historia manteniendo el interés (<i>Are you ready for this? · But that's not all! · Wouldn't you know it?</i>) y reaccionar como oyente (<i>Don't tell me you…! · You must be joking!</i>)",
      "Cambiar o retomar el tema con <i>Anyway…</i>",
    ],
    map: [
      ['Vocabulary', '9 colocaciones de <i>talking about discoveries</i> (<i>carry out research, face a challenge, gain knowledge, make a breakthrough / a connection / a discovery, notice a phenomenon, provide insight / a solution</i>) y 12 de <i>right and wrong</i> (<i>blame, blunder, confusion, correct a mistake, epic fail, fault, fix a problem, get something wrong, make a mistake, make something right, misunderstanding, mix-up</i>)', 'Flashcards con audio, expresión ↔ definición, situación → expresión, verbo + sustantivo, ¿cuál de los dos?'],
      ['Grammar', '<b>Past unreal conditionals</b> (tercer condicional): <i>if</i> + past perfect → <i>would / might have</i> + participio; preguntas y respuestas cortas. <b>Modals of past probability</b>: <i>could / couldn\'t have</i>, <i>should(n\'t) have</i> (crítica), <i>may / might have</i> (suposición), <i>must have</i> (certeza); contracciones habladas <i>should\'ve, couldn\'t\'ve</i>', 'Elige la forma, ¿segundo o tercero?, elige el modal según la certeza, ¿qué quiere decir?, corrige errores típicos, ordena mini-diálogos, reescribe arrepentimientos y deducciones, repaso Units 6-9'],
      ['Listening', 'Un despliegue que salió mal contado con suspense; una factura equivocada y lo que debió pasar', 'Dictado con voz sintética y dos diálogos nuevos con preguntas'],
      ['Speaking', 'Tu epic fail, tres "si hubiera…", deducir qué pasó, un descubrimiento en la tesis, arreglar las cosas con un cliente', 'Retos con cronómetro y reconocimiento de voz; contracciones <i>would\'ve / shouldn\'t have / couldn\'t\'ve</i> y sílaba tónica de <i>BREAKthrough, pheNOmenon, disCOvery</i>'],
      ['Reading', 'Descubrimientos por accidente: penicilina, microondas y Post-it', 'Texto nuevo con terceros condicionales y modales de pasado + inferir significado'],
      ['Writing', 'La historia de un error (con lo que habrías hecho distinto) y un mensaje para arreglar las cosas con un cliente', 'Corrige errores típicos (<i>if I would have, should have went, did a mistake, blame me of…</i>), añade ganchos a una historia plana, escribe con checklist'],
      ['Social English', '<i>Are you ready for this? · But that\'s not all! · Isn\'t that amazing? · Wouldn\'t you know it? · You can imagine! · You know what? · You won\'t believe this, but… · Don\'t tell me you…! · Let me guess – you…! · That\'s so funny / crazy / awful! · You can\'t be serious! · You must be joking! · Anyway…</i>', 'Ordenar diálogos, respuesta rápida, reaccionar como oyente, role-play con ramas'],
    ],

    sections: [
      { id: 'home', label: 'Inicio', render: 'overview', activities: [] },

      /* ================= VOCABULARY ================= */
      { id: 'vocab', label: 'Vocabulary', activities: [
        { label: 'Flashcards', type: 'flashcards', eyebrow: 'Flashcards con audio', title: 'Toca la tarjeta para girarla', intro: 'Anverso: la expresión. Reverso: significado, ejemplo del curso y una pregunta para ti. Casi todo el vocabulario de esta unidad son <b>colocaciones</b> (verbo + sustantivo): apréndelas en bloque, no palabra por palabra. Pulsa 🔊 para oír la pronunciación.',
          cards: [
            ...DS.map(t => ({ cat: 'Talking about discoveries', w: t[0], def: t[1], ex: t[3], ask: t[4] })),
            ...RW.map(t => ({ cat: 'Right and wrong', w: t[0], def: t[1], ex: t[3], ask: t[4] })),
          ] },
        { label: 'Discoveries ↔ Definición', type: 'match', eyebrow: 'Talking about discoveries', title: 'Empareja la expresión con su definición', intro: 'Toca una expresión de la izquierda y luego su definición (en inglés, como en el curso) a la derecha.',
          pairs: DS.map(t => [t[0], t[2]]), round: 5 },
        { label: 'Right and wrong ↔ Definición', type: 'match', eyebrow: 'Discussing right and wrong', title: 'Empareja la expresión con su definición', intro: 'Las 12 expresiones de culpa, error y arreglo. Pista: tres son sustantivos de "lío" (<i>confusion, misunderstanding, mix-up</i>), dos son de culpa (<i>blame, fault</i>) y el resto son acciones.',
          pairs: RW.map(t => [t[0], t[2]]), round: 6 },
        { label: '¿Qué expresión es?', type: 'mcq', eyebrow: 'En contexto', title: 'Lee la situación y elige la expresión', intro: 'Descubrimientos y errores mezclados. Varias situaciones son de un programador de banco con un negocio de empanadas… ¿te suena?', pool: 8,
          build: ({ pick, esc }) => pick(SIT, 8).map(s => { const t = findW(s[2]); const bad = SITW.filter(x => x !== s[1] && !s[3].includes(x)); return { q: esc(s[0]).replace('___', '<span class="blank">?</span>'), opts: [s[1], ...pick(bad, 3)], a: s[1], why: `<b>${t[0]}</b> — ${t[1]}. “${t[3]}”` }; }) },
        { label: 'Verbo + sustantivo', type: 'mcq', eyebrow: 'Colocaciones', title: 'Elige el verbo que acompaña al sustantivo', intro: 'El corazón de la unidad: <b>make</b> a breakthrough / a connection / a discovery / a mistake / it right · <b>carry out</b> research · <b>gain</b> knowledge · <b>face</b> a challenge · <b>notice</b> a phenomenon · <b>provide</b> insight / a solution · <b>fix</b> a problem · <b>correct</b> a mistake · <b>get</b> something wrong. Ojo: en inglés no se "hace" (<i>do</i>) un error ni una investigación.', pool: 8, items: [
          { blank: 1, q: 'Fleming ___ a discovery that changed medicine.', opts: ['made', 'did', 'got', 'carried out'], a: 'made', why: '<b>make a discovery</b>. <i>Do</i> no se usa con <i>discovery</i>.' },
          { blank: 1, q: 'Our team has been ___ research on customer behavior for a year.', opts: ['carrying out', 'making', 'doing out', 'facing'], a: 'carrying out', why: '<b>carry out research</b> (también <i>do research</i>, pero no <i>make research</i>).' },
          { blank: 1, q: 'You ___ knowledge every time you fix a bug you did not write.', opts: ['gain', 'win', 'earn', 'make'], a: 'gain', why: '<b>gain knowledge</b>. <i>Win</i> es ganar un premio; <i>earn</i>, dinero.' },
          { blank: 1, q: 'Small businesses ___ a challenge every time prices go up.', opts: ['face', 'make', 'notice', 'provide'], a: 'face', why: '<b>face a challenge</b> = enfrentar un reto.' },
          { blank: 1, q: 'After months of tests, the lab finally ___ a breakthrough.', opts: ['made', 'did', 'got', 'gained'], a: 'made', why: '<b>make a breakthrough</b>.' },
          { blank: 1, q: 'Newton ___ a phenomenon that everybody else had ignored.', opts: ['noticed', 'made', 'provided', 'faced'], a: 'noticed', why: '<b>notice a phenomenon</b> = darse cuenta de que algo ocurre.' },
          { blank: 1, q: 'The interviews ___ insight into why users leave the app after a week.', opts: ['provided', 'made', 'noticed', 'carried out'], a: 'provided', why: '<b>provide insight (into)</b>. Fíjate en la preposición: <i>insight into</i>.' },
          { blank: 1, q: 'I ___ a connection between the slow queries and the new index.', opts: ['made', 'did', 'got', 'took'], a: 'made', why: '<b>make a connection</b> = atar cabos.' },
          { blank: 1, q: 'Everybody ___ mistakes; good teams learn from them.', opts: ['makes', 'does', 'gets', 'has'], a: 'makes', why: '<b>make a mistake</b>. El error número uno del hispanohablante es <s>do a mistake</s>.' },
          { blank: 1, q: 'I ___ two answers wrong on the certification exam.', opts: ['got', 'made', 'did', 'took'], a: 'got', why: '<b>get something wrong</b>: <i>I got two answers wrong</i>.' },
          { blank: 1, q: 'We sent the wrong empanadas, but we ___ it right with a free order.', opts: ['made', 'did', 'fixed', 'corrected'], a: 'made', why: '<b>make it right</b> = arreglar las cosas con la persona. <i>Fix</i> va con <i>problem</i>.' },
          { blank: 1, q: 'Can you ___ the problem with the login before 9 a.m.?', opts: ['fix', 'make', 'correct', 'face'], a: 'fix', why: '<b>fix a problem</b>. <i>Correct</i> va con <i>mistake / error</i>.' },
          { blank: 1, q: 'Read the email again and ___ the mistakes before you send it.', opts: ['correct', 'fix', 'make', 'provide'], a: 'correct', why: '<b>correct a mistake</b>. También <i>fix a mistake</i> en registro informal, pero el curso enseña <i>correct</i>.' },
          { blank: 1, q: 'Instead of complaining, she ___ a solution: a shared calendar.', opts: ['provided', 'made', 'noticed', 'gained'], a: 'provided', why: '<b>provide a solution</b>.' },
        ] },
        { label: '¿Cuál de los dos?', type: 'mcq', eyebrow: 'Matices', title: 'Elige la palabra que encaja', intro: 'Las palabras de "lío" y de "culpa" se parecen: <b>fault</b> (mi responsabilidad: <i>my fault</i>) · <b>blame</b> (echar la culpa: <i>blame someone for</i>) · <b>mistake / error</b> (equivocación) · <b>blunder</b> (error grave y tonto) · <b>epic fail</b> (desastre vergonzoso, informal) · <b>misunderstanding</b> (dos personas entendieron cosas distintas) · <b>mix-up</b> (se cruzaron dos cosas) · <b>confusion</b> (nadie entiende qué pasa).', pool: 8, items: [
          { blank: 1, q: "I'm sorry, that was my ___. I'll pay for the broken glass.", opts: ['fault', 'blame', 'blunder', 'confusion'], a: 'fault', why: '<b>my fault</b> = fue culpa mía. <i>Blame</i> es el verbo o "la culpa que se echa": <i>don\'t blame me</i>.' },
          { blank: 1, q: "Don't ___ me for the crash. I wasn't even on call.", opts: ['blame', 'fault', 'mix up', 'confuse'], a: 'blame', why: '<b>blame someone for something</b>. <i>Fault</i> no es verbo en este sentido.' },
          { blank: 1, q: 'You ordered a cappuccino and I brought an espresso. Sorry for the ___.', opts: ['misunderstanding', 'blunder', 'epic fail', 'confusion'], a: 'misunderstanding', why: 'Dos personas entendieron cosas distintas → <b>misunderstanding</b>.' },
          { blank: 1, q: 'Two customers got each other\'s orders. It was a ___ in the kitchen.', opts: ['mix-up', 'misunderstanding', 'fault', 'blunder'], a: 'mix-up', why: 'Dos cosas se cruzaron → <b>mix-up</b>.' },
          { blank: 1, q: 'The new password policy created so much ___ that nobody could log in on Monday.', opts: ['confusion', 'mix-up', 'fault', 'blame'], a: 'confusion', why: 'Estado general de no entender → <b>confusion</b> (incontable).' },
          { blank: 1, q: 'Calling the client by the wrong name during the demo was a serious ___.', opts: ['blunder', 'confusion', 'mix-up', 'fault'], a: 'blunder', why: 'Error grave y un poco tonto → <b>blunder</b>.' },
          { blank: 1, q: 'My first attempt at a soufflé was an ___: it looked like a pancake.', opts: ['epic fail', 'misunderstanding', 'insight', 'error'], a: 'epic fail', why: 'Desastre total y vergonzoso, en tono informal → <b>epic fail</b>.' },
          { blank: 1, q: 'There is an ___ on my bill: it says I called Japan.', opts: ['error', 'epic fail', 'insight', 'blame'], a: 'error', why: 'Equivocación concreta en un documento → <b>error</b> (o <i>mistake</i>).' },
          { blank: 1, q: 'The satellite data ___ insight into the climate of Mars.', opts: ['provided', 'made', 'fixed', 'faced'], a: 'provided', why: '<b>provide insight</b>.' },
          { blank: 1, q: 'We can\'t undo the mistake, but we can ___ it right: a refund and a new order.', opts: ['make', 'do', 'fix', 'correct'], a: 'make', why: '<b>make it right</b> = compensar / arreglar las cosas.' },
          { blank: 1, q: 'Before Newton, nobody had made the ___ between a falling apple and the Moon.', opts: ['connection', 'discovery', 'breakthrough', 'solution'], a: 'connection', why: 'Relación entre dos cosas → <b>make a connection</b>.' },
          { blank: 1, q: 'A ___ is a big step that solves a problem; a discovery is finding something new.', opts: ['breakthrough', 'phenomenon', 'challenge', 'mix-up'], a: 'breakthrough', why: '<b>breakthrough</b> = avance decisivo.' },
          { blank: 1, q: 'I ___ the date wrong: the meeting was on Tuesday, not Thursday.', opts: ['got', 'made', 'did', 'blamed'], a: 'got', why: '<b>get something wrong</b>: <i>I got the date wrong</i>.' },
          { blank: 1, q: 'Space travel is a ___ nobody has fully solved yet.', opts: ['challenge', 'phenomenon', 'blunder', 'fault'], a: 'challenge', why: 'Algo difícil que pone a prueba → <b>challenge</b>.' },
        ] },
      ] },

      /* ================= GRAMMAR ================= */
      { id: 'grammar', label: 'Grammar', activities: [
        { label: 'Notas', type: 'notes', eyebrow: 'Past unreal conditionals · Modals of past probability', title: 'Imaginar otro pasado y deducir qué pasó', html: `
          <h3>1 · Past unreal conditionals (tercer condicional)</h3>
          <p style="margin:8px 0 14px">Hablas de una situación <b>imaginada en el pasado</b>: algo que no ocurrió (o que ocurrió y lamentas). La cláusula con <i>if</i> va en <b>past perfect</b> y la principal lleva <b>would have</b> (o <b>might have</b>) + participio.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Parte</th><th>Forma</th><th>Ejemplo del curso</th><th>Pista</th></tr></thead><tbody>
            <tr><td><b>If clause</b> (situación imaginada)</td><td><b>if</b> + sujeto + <b>had</b> + participio</td><td><b>If I had walked</b> into the building, I wouldn't have broken my toe.</td><td>En realidad no entré caminando. Nunca <s>if I would have</s>, <s>if I had went</s>.</td></tr>
            <tr><td><b>Main clause</b> (resultado imaginado)</td><td>sujeto + <b>would have</b> + participio</td><td>If I had walked in, <b>I wouldn't have broken</b> my toe.</td><td><i>would've</i> en el habla. Después de <i>have</i>, <b>participio</b>: <s>would have broke</s>.</td></tr>
            <tr><td><b>might have</b> en vez de <i>would have</i></td><td>sujeto + <b>might have</b> + participio</td><td>I <b>might never have met</b> my wife if I hadn't broken my toe.</td><td><i>might</i> = resultado solo <b>posible</b>; <i>would</i> = seguro (dentro de lo imaginado).</td></tr>
            <tr><td><b>Pregunta</b></td><td><b>would</b> + sujeto + <b>have</b> + participio…, <i>if</i> + past perfect</td><td><b>Would you have avoided</b> that accident if you had just walked into the building?</td><td>Solo la cláusula principal cambia de orden; la de <i>if</i> no.</td></tr>
            <tr><td><b>Respuesta corta</b></td><td><b>would / might (not) have</b></td><td>"I <b>might have</b>. No, I probably <b>would have</b>."</td><td>No repitas el participio: <i>Yes, I would have</i>.</td></tr>
            <tr><td><b>Comas</b></td><td><i>if</i> primero → coma; principal primero → sin coma</td><td><b>If I had checked the address,</b> we wouldn't have gotten lost.<br>We wouldn't have gotten lost <b>if I had checked</b> the address.</td><td>Igual que en Units 2 y 8.</td></tr>
          </tbody></table></div>
          <div class="hint" style="margin-top:14px"><b>Los tres condicionales juntos.</b> <b>Real</b> (Unit 2): <i>If I <b>test</b> the code, it <b>will</b> work</i> (todavía puedo). <b>Imaginado ahora</b> (Unit 8): <i>If I <b>tested</b> more, it <b>would</b> work</i> (no lo hago). <b>Imaginado en el pasado</b> (Unit 10): <i>If I <b>had tested</b> it, it <b>would have worked</b></i> (no lo probé y ya pasó). La pregunta clave: ¿el pasado puede cambiarse? No → tercer condicional. En la cláusula de <i>if</i> <b>nunca</b> va <i>would</i>, en ningún condicional.</div>
          <h3 style="margin-top:22px">2 · Modals of past probability</h3>
          <p style="margin:8px 0 14px">Para deducir, suponer o criticar algo del pasado: <b>modal + have + participio</b>. El modal da el grado de certeza; <i>have</i> + participio lo manda al pasado.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Modal</th><th>Significado</th><th>Ejemplo del curso</th><th>Pista</th></tr></thead><tbody>
            <tr><td><b>must have</b></td><td>Estoy <b>seguro</b>: es la única conclusión lógica</td><td>Wanda <b>must have practiced</b> more than Wayne.</td><td>Deducción con pruebas. Negativo de certeza: <i>couldn't have</i> / <i>can't have</i>, no <s>mustn't have</s> (raro en inglés americano).</td></tr>
            <tr><td><b>may / might have</b></td><td><b>Quizá</b>: estoy suponiendo</td><td>She <b>may not have studied</b> as much as her brother.<br>I think she <b>might have gone</b> to work, but I'm not sure.</td><td><i>might have</i> + <i>but I'm not sure</i>: la fórmula de la suposición.</td></tr>
            <tr><td><b>could have</b></td><td>Era <b>posible</b>, pero no pasó</td><td>You <b>could have made</b> it more interesting.</td><td>Oportunidad perdida: "pudiste haberlo hecho". A veces suena a reproche suave.</td></tr>
            <tr><td><b>couldn't have</b></td><td>Era <b>imposible</b> / estoy seguro de que no</td><td>They simply <b>couldn't have tried</b> harder.</td><td>= hicieron todo lo posible. <i>Couldn't have</i> es el negativo fuerte de <i>must have</i>.</td></tr>
            <tr><td><b>should (not) have</b></td><td><b>Evaluar o criticar</b>: era lo correcto y no se hizo (o al revés)</td><td>She <b>should not have done</b> the act alone.<br>I think you <b>should have said</b> something at the end.</td><td>Arrepentimiento o crítica. <i>I should've known</i> = debí saberlo.</td></tr>
          </tbody></table></div>
          <div class="hint" style="margin-top:14px"><b>Al hablar se contrae <i>have</i>, al escribir no.</b> <i>It should have been longer</i> (escrito) → "It <b>should've</b> been longer" (hablado). <i>You couldn't have done better</i> → "You <b>couldn't've</b> done better". Por eso mucha gente escribe mal <s>should of</s>: lo que oyen es /ʃʊdəv/. Escribe siempre <b>should have</b>.</div>
          <div class="hint small" style="margin-top:12px"><b>Trampas típicas del hispanohablante:</b> <s>If I would have known</s> → <b>If I had known</b> · <s>I would had fixed it</s> → <b>I would have fixed</b> it · <s>should have went</s> → <b>should have gone</b> (participio, no pasado) · <s>must had forgotten</s> → <b>must have forgotten</b> (<i>have</i> no cambia) · <s>If I had know</s> → <b>If I had known</b> · <s>can't have did</s> → <b>can't have done</b> · <s>should of</s> → <b>should have</b> · <s>If I had had more time, I would finish</s> → <b>I would have finished</b> (si el <i>if</i> es pasado, el resultado también).</div>` },
        { label: 'Tercer condicional', type: 'mcq', eyebrow: 'Past unreal conditionals', title: 'Elige la forma correcta', intro: 'Situaciones del pasado que imaginas distintas. <i>If</i> + <b>had</b> + participio, y <b>would / might have</b> + participio en la otra cláusula.', pool: 8, items: [
          { blank: 1, q: 'If I ___ the address twice, we wouldn\'t have delivered the empanadas to Comas.', opts: ['had checked', 'would have checked', 'checked', 'have checked'], a: 'had checked', why: 'Cláusula de <i>if</i> → <b>past perfect</b>. <s>If I would have</s> es el error número uno.' },
          { blank: 1, q: "If the team had tested the release on Thursday, the deployment ___ on Friday.", opts: ["wouldn't have failed", "wouldn't fail", "didn't fail", "wouldn't have fail"], a: "wouldn't have failed", why: 'Resultado imaginado en el pasado → <b>wouldn\'t have</b> + participio (<i>failed</i>).' },
          { blank: 1, q: 'I ___ the thesis earlier if I hadn\'t started the food business.', opts: ['might have finished', 'might finished', 'might have finish', 'finished'], a: 'might have finished', why: '<b>might have</b> + participio = resultado posible, no seguro.' },
          { blank: 1, q: "Fleming wouldn't have discovered penicillin if he ___ his lab before his vacation.", opts: ['had cleaned', 'cleaned', 'would have cleaned', 'has cleaned'], a: 'had cleaned', why: 'No limpió (por suerte). Cláusula de <i>if</i> → <b>had cleaned</b>.' },
          { blank: 1, q: '___ the job if they had offered you more money?', opts: ['Would you have accepted', 'Would you accepted', 'Had you accepted', 'Did you accept'], a: 'Would you have accepted', why: 'Pregunta: <b>would</b> + sujeto + <b>have</b> + participio. La cláusula de <i>if</i> no cambia.' },
          { blank: 1, q: '"Would you have called the client?" "I ___. I\'m not sure."', opts: ['might have', 'might', 'might had', 'would'], a: 'might have', why: 'Respuesta corta: <b>might (not) have</b>. Frase del curso: <i>I might have. No, I probably would have.</i>' },
          { blank: 1, q: 'If she ___ the error on the bill, she would have paid for calls to China.', opts: ["hadn't noticed", "didn't notice", "wouldn't have noticed", "hasn't noticed"], a: "hadn't noticed", why: 'Negativa en la cláusula de <i>if</i>: <b>hadn\'t</b> + participio.' },
          { blank: 1, q: 'We ___ the connection between the two bugs if Marco hadn\'t read the old logs.', opts: ['would never have made', 'would never make', 'never made', 'had never made'], a: 'would never have made', why: '<i>never</i> se coloca entre <i>would</i> y <i>have</i>: <b>would never have made</b>.' },
          { blank: 1, q: "I might never have met my wife if I ___ my toe.", opts: ["hadn't broken", "didn't break", "wouldn't have broken", "haven't broken"], a: "hadn't broken", why: 'Frase del curso: <i>if I <b>hadn\'t broken</b> my toe</i>.' },
          { blank: 1, q: "If the customer had written the address clearly, there ___ a mix-up.", opts: ["wouldn't have been", "wouldn't be", "wasn't", "hadn't been"], a: "wouldn't have been", why: '<i>there would(n\'t) have been</i> = (no) habría habido.' },
          { blank: 1, q: 'If I ___ about the meeting, I would have prepared the numbers.', opts: ['had known', 'had knew', 'would have known', 'knew'], a: 'had known', why: 'Participio de <i>know</i>: <b>known</b>. <s>had knew</s> no existe.' },
          { blank: 1, q: "They ___ the breakthrough without ten years of research.", opts: ["wouldn't have made", "wouldn't make", "didn't make", "hadn't made"], a: "wouldn't have made", why: 'Condición implícita (<i>without…</i> = si no hubieran investigado) → <b>wouldn\'t have made</b>.' },
          { blank: 1, q: 'If you had told me it was your fault, I ___ so angry.', opts: ["wouldn't have been", "wouldn't be", "weren't", "wasn't"], a: "wouldn't have been", why: 'Pasado imaginado → <b>wouldn\'t have been</b>.' },
          { blank: 1, q: 'If the server ___ at 2 a.m., nobody would have noticed the error until Monday.', opts: ["hadn't crashed", "didn't crash", "wouldn't crash", "hasn't crashed"], a: "hadn't crashed", why: 'Sí se cayó (y por eso lo vimos). Imaginado al revés → <b>hadn\'t crashed</b>.' },
          { blank: 1, q: 'Would you have avoided that accident if you ___ into the building?', opts: ['had just walked', 'just walked', 'would just walk', 'have just walked'], a: 'had just walked', why: 'Frase del curso: <i>if you <b>had just walked</b> into the building</i>.' },
          { blank: 1, q: "If I had had more time, I ___ the report before the demo.", opts: ['would have corrected', 'would correct', 'corrected', 'had corrected'], a: 'would have corrected', why: '<i>had had</i> (past perfect de <i>have</i>) en el <i>if</i> → <b>would have corrected</b> en el resultado.' },
        ] },
        { label: '¿Segundo o tercero?', type: 'mcq', eyebrow: 'Second vs third conditional', title: 'Elige la frase que encaja con el contexto', intro: 'Lee el contexto en español. Si imaginas el <b>presente / futuro</b> distinto, segundo condicional (Unit 8: <i>if</i> + pasado → <i>would</i>). Si imaginas el <b>pasado</b> distinto (ya ocurrió, no se puede cambiar), tercero (<i>if</i> + past perfect → <i>would have</i>).', pool: 8, items: [
          { q: 'El viernes desplegaste sin probar y falló. Ya pasó; lo lamentas.', opts: ["If I had tested it, it wouldn't have failed.", "If I tested it, it wouldn't fail.", "If I would have tested it, it didn't fail."], a: "If I had tested it, it wouldn't have failed.", why: 'Pasado que no puede cambiarse → <b>tercer condicional</b>.' },
          { q: 'No tienes laboratorio propio. Imaginas cómo sería investigar con uno (ahora).', opts: ['If I had a lab, I would carry out my own research.', 'If I had had a lab, I would have carried out my own research.', 'If I would have a lab, I carry out research.'], a: 'If I had a lab, I would carry out my own research.', why: 'Situación presente imaginada → <b>segundo condicional</b>.' },
          { q: 'Ayer no apuntaste bien la dirección y el pedido se perdió.', opts: ["If I had written down the address correctly, the order wouldn't have gotten lost.", "If I wrote down the address correctly, the order wouldn't get lost.", "If I write down the address, the order won't get lost."], a: "If I had written down the address correctly, the order wouldn't have gotten lost.", why: 'Error ya cometido → <b>tercer condicional</b>.' },
          { q: 'Tu amiga te pide consejo hoy. Te pones en su lugar.', opts: ["If I were you, I'd apologize and make it right.", "If I had been you, I would have apologized.", "If I would be you, I apologize."], a: "If I were you, I'd apologize and make it right.", why: 'Consejo sobre el presente → <b>If I were you, I\'d…</b> (Unit 8).' },
          { q: 'Fleming no limpió su laboratorio antes de las vacaciones y así descubrió la penicilina (1928).', opts: ["If Fleming had cleaned his lab, he wouldn't have discovered penicillin.", "If Fleming cleaned his lab, he wouldn't discover penicillin.", "If Fleming cleans his lab, he won't discover penicillin."], a: "If Fleming had cleaned his lab, he wouldn't have discovered penicillin.", why: 'Hecho histórico → <b>tercer condicional</b>.' },
          { q: 'Hoy en general: no tienes tiempo para leer papers, y te gustaría.', opts: ['If I had more time, I would read more research.', 'If I had had more time, I would have read more research.', 'If I have more time, I would read more research.'], a: 'If I had more time, I would read more research.', why: 'Realidad presente (no tengo tiempo) → <b>segundo condicional</b>.' },
          { q: 'La semana pasada tu compañero no leyó los logs y tardaron dos días en encontrar el bug.', opts: ['If he had read the logs, we would have found the bug in an hour.', 'If he read the logs, we would find the bug in an hour.', 'If he reads the logs, we find the bug.'], a: 'If he had read the logs, we would have found the bug in an hour.', why: 'Ya pasó → <b>tercer condicional</b>.' },
          { q: 'Imaginas que el cliente hubiera llamado antes (no lo hizo) y que entonces quizá habrías llegado a tiempo.', opts: ['If the customer had called earlier, I might have arrived on time.', 'If the customer called earlier, I might arrive on time.', 'If the customer had called earlier, I might arrive on time.'], a: 'If the customer had called earlier, I might have arrived on time.', why: 'Pasado + resultado posible → <i>if</i> + past perfect, <b>might have</b> + participio. No mezcles tiempos.' },
          { q: 'Ganar la lotería: no juegas, pura fantasía sobre el futuro.', opts: ["If I won the lottery, I'd open a research foundation.", "If I had won the lottery, I would have opened a foundation.", "If I would win the lottery, I open a foundation."], a: "If I won the lottery, I'd open a research foundation.", why: 'Futuro improbable → <b>segundo condicional</b>.' },
          { q: 'En la reunión de ayer te equivocaste de nombre. Lo lamentas.', opts: ["If I had prepared better, I wouldn't have made that blunder.", "If I prepared better, I wouldn't make that blunder.", "If I would have prepared, I wouldn't make that blunder."], a: "If I had prepared better, I wouldn't have made that blunder.", why: 'Metedura de pata pasada → <b>tercer condicional</b>.' },
          { q: 'Preguntas a tu amiga qué habría hecho ella en tu lugar ayer.', opts: ['What would you have done if you had been in my shoes?', 'What would you do if you were in my shoes?', 'What would you have done if you were in my shoes yesterday?'], a: 'What would you have done if you had been in my shoes?', why: 'Situación pasada → pregunta en tercer condicional, las dos cláusulas en pasado.' },
          { q: 'Regla general del equipo: cada vez que alguien despliega un viernes, todos se quedan tarde.', opts: ['If someone deploys on a Friday, everybody stays late.', 'If someone deployed on a Friday, everybody would stay late.', 'If someone had deployed on a Friday, everybody would have stayed late.'], a: 'If someone deploys on a Friday, everybody stays late.', why: 'Hecho general → presente + presente (condicional cero, Unit 2). No es imaginado.' },
        ] },
        { label: 'Modales de pasado', type: 'mcq', eyebrow: 'Modals of past probability', title: 'Elige el modal según la certeza', intro: 'Pregúntate: ¿estoy <b>seguro</b>? → <i>must have</i>. ¿Seguro de que <b>no</b>? → <i>couldn\'t / can\'t have</i>. ¿<b>Quizá</b>? → <i>might / may have</i>. ¿Era <b>posible</b> pero no pasó? → <i>could have</i>. ¿<b>Critico</b> o lamento? → <i>should(n\'t) have</i>.', pool: 8, items: [
          { blank: 1, q: "The lights are off and his car isn't here. He ___ home already. (sure)", opts: ['must have gone', 'might have gone', "couldn't have gone", 'should have gone'], a: 'must have gone', why: 'Pruebas claras, única conclusión lógica → <b>must have</b>.' },
          { blank: 1, q: "She isn't answering. She ___ to the gym, but I'm not sure.", opts: ['might have gone', 'must have gone', "can't have gone", 'should have gone'], a: 'might have gone', why: '<i>but I\'m not sure</i> = suposición → <b>might have</b>.' },
          { blank: 1, q: "You ___ the client's name wrong. It was printed on every slide! (criticism)", opts: ["shouldn't have gotten", "mustn't have gotten", "couldn't have gotten", "might not have gotten"], a: "shouldn't have gotten", why: 'Crítica de una acción pasada → <b>shouldn\'t have</b> + participio.' },
          { blank: 1, q: "Marco ___ the bug; he was on vacation in Cusco that week. (impossible)", opts: ["couldn't have introduced", 'must have introduced', 'should have introduced', 'might have introduced'], a: "couldn't have introduced", why: 'Era imposible → <b>couldn\'t have</b>.' },
          { blank: 1, q: 'The presentation was fine, but you ___ it more interesting with a demo. (missed opportunity)', opts: ['could have made', 'must have made', "can't have made", 'may have made'], a: 'could have made', why: 'Frase del curso: <i>You <b>could have made</b> it more interesting</i>. Era posible, no se hizo.' },
          { blank: 1, q: 'Wanda won every game. She ___ more than Wayne. (sure)', opts: ['must have practiced', 'might have practiced', "shouldn't have practiced", "couldn't have practiced"], a: 'must have practiced', why: 'Frase del curso: deducción segura → <b>must have practiced</b>.' },
          { blank: 1, q: 'They lost the final, but they simply ___ harder. (they did everything possible)', opts: ["couldn't have tried", "shouldn't have tried", 'must have tried', 'might have tried'], a: "couldn't have tried", why: 'Frase del curso: <i>They simply <b>couldn\'t have tried</b> harder</i> = imposible esforzarse más.' },
          { blank: 1, q: 'The order went to the wrong address. I ___ it twice before leaving. (regret)', opts: ['should have checked', 'must have checked', "can't have checked", 'could have checked'], a: 'should have checked', why: 'Arrepentimiento: era lo correcto y no lo hice → <b>should have</b>.' },
          { blank: 1, q: "My bill says I called China. The company ___ a mistake; I've never called China.", opts: ['must have made', 'might not have made', "shouldn't have made", "couldn't have made"], a: 'must have made', why: 'Única explicación lógica → <b>must have made</b> a mistake.' },
          { blank: 1, q: "She ___ as much as her brother. That would explain her grades. (guess)", opts: ['may not have studied', "mustn't have studied", "couldn't have studied", 'should have studied'], a: 'may not have studied', why: 'Frase del curso: suposición negativa → <b>may not have</b>.' },
          { blank: 1, q: "She ___ the act alone; it was too dangerous. (criticism)", opts: ['should not have done', 'must not have done', 'could not have done', 'may not have done'], a: 'should not have done', why: 'Frase del curso: <i>She <b>should not have done</b> the act alone</i>.' },
          { blank: 1, q: "I think you ___ something at the end of the meeting. Everybody was waiting for your opinion.", opts: ['should have said', 'must have said', "can't have said", 'might have said'], a: 'should have said', why: 'Frase del curso: evaluación → <b>should have said</b>.' },
          { blank: 1, q: "The kitchen was a disaster when I came back. My nephew ___ to cook again. (sure)", opts: ['must have tried', 'should have tried', "couldn't have tried", 'may have tried'], a: 'must have tried', why: 'Deducción segura por las pruebas → <b>must have</b>.' },
          { blank: 1, q: "You ___ me! I would have brought the backup drive. (criticism)", opts: ['should have told', 'must have told', 'might have told', "can't have told"], a: 'should have told', why: 'Reproche → <b>should have told</b> me.' },
          { blank: 1, q: "The experiment ___ at any time; nobody was checking the temperature. (it was possible)", opts: ['could have failed', 'must have failed', "can't have failed", 'should have failed'], a: 'could have failed', why: 'Posibilidad en el pasado (no pasó, pero pudo pasar) → <b>could have failed</b>.' },
          { blank: 1, q: "Two hundred empanadas in Comas instead of Chorrillos? There ___ a mix-up with the addresses.", opts: ['must have been', 'should have been', "couldn't have been", 'might not have been'], a: 'must have been', why: 'Explicación segura → <b>there must have been</b> a mix-up.' },
        ] },
        { label: '¿Qué quiere decir?', type: 'mcq', eyebrow: 'Interpretar modales', title: 'Elige el significado de la frase', intro: 'Ahora al revés: lee la frase con el modal y elige qué quiere decir el hablante. Fíjate en el modal, no en el verbo.', pool: 8, items: [
          { q: '"You should have told me about the bug."', opts: ["You didn't tell me, and that was wrong.", "You probably told me, but I forgot.", "It was impossible for you to tell me."], a: "You didn't tell me, and that was wrong.", why: '<b>should have</b> = crítica: era lo correcto y no se hizo.' },
          { q: '"She must have forgotten the meeting."', opts: ["I'm almost sure she forgot.", "She was obliged to forget.", "Maybe she forgot, maybe not."], a: "I'm almost sure she forgot.", why: '<b>must have</b> = deducción segura, no obligación.' },
          { q: '"He might have taken the highway."', opts: ["It's possible, but I'm not sure.", "I'm sure he took it.", "He wasn't allowed to take it."], a: "It's possible, but I'm not sure.", why: '<b>might have</b> = suposición.' },
          { q: '"They couldn\'t have finished the project without you."', opts: ['It would have been impossible for them to finish it alone.', "They didn't finish the project.", 'They finished it, but badly.'], a: 'It would have been impossible for them to finish it alone.', why: '<b>couldn\'t have</b> = imposible (y por tanto, un cumplido).' },
          { q: '"You could have called me!"', opts: ["It was possible to call me, and you didn't. (reproach)", "You called me, thanks.", "You weren't able to call me."], a: "It was possible to call me, and you didn't. (reproach)", why: '<b>could have</b> + ! = oportunidad perdida, reproche suave.' },
          { q: '"If I had known, I would have brought an umbrella."', opts: ["I didn't know, so I didn't bring one.", "I knew, so I brought one.", "I might bring one tomorrow."], a: "I didn't know, so I didn't bring one.", why: 'Tercer condicional: las dos cosas son lo contrario de lo que pasó.' },
          { q: '"I shouldn\'t have deployed on a Friday."', opts: ["I deployed on a Friday and I regret it.", "I didn't deploy on Friday, luckily.", "I'm not allowed to deploy on Fridays."], a: "I deployed on a Friday and I regret it.", why: '<b>shouldn\'t have</b> = lo hice y fue un error.' },
          { q: '"It can\'t have been Marco; he was in Cusco."', opts: ["I'm sure it wasn't Marco.", "Maybe it was Marco.", "Marco wasn't able to go to Cusco."], a: "I'm sure it wasn't Marco.", why: '<b>can\'t / couldn\'t have</b> = certeza negativa.' },
          { q: '"We would have arrived on time if the toll plaza hadn\'t been closed."', opts: ["The toll plaza was closed, so we arrived late.", "We arrived on time.", "The toll plaza is usually closed."], a: "The toll plaza was closed, so we arrived late.", why: 'Tercer condicional: realidad = cerrado + tarde.' },
          { q: '"I might never have met my wife if I hadn\'t broken my toe."', opts: ["Breaking my toe led to meeting my wife.", "I never met my wife.", "I didn't break my toe."], a: "Breaking my toe led to meeting my wife.", why: 'Frase del curso: la "desgracia" fue la causa de algo bueno.' },
        ] },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · errores típicos de la unidad', title: 'Reescribe la frase corrigiendo el error', intro: 'Los errores más frecuentes del hispanohablante con el tercer condicional y los modales de pasado. Un solo error por frase.', items: [
          { bad: 'If I would have known about the bug, I would have fixed it.', good: 'If I had known about the bug, I would have fixed it.', why: 'En la cláusula de <i>if</i> va <b>past perfect</b>, nunca <i>would</i>: <i>If I <b>had known</b></i>.' },
          { bad: 'If we had tested the code, we would had found the error.', good: 'If we had tested the code, we would have found the error.', why: 'Después de <i>would</i> va <b>have</b>, no <i>had</i>: <i>would <b>have</b> found</i>.' },
          { bad: 'You should have went to the doctor.', good: 'You should have gone to the doctor.', why: 'Después de <i>have</i>, <b>participio</b>: <i>gone</i>, no el pasado <i>went</i>.' },
          { bad: 'She must had forgotten the meeting.', good: 'She must have forgotten the meeting.', why: '<i>Have</i> no cambia después de un modal: <b>must have</b> + participio.' },
          { bad: "If I had know the address, I wouldn't have gotten lost.", good: "If I had known the address, I wouldn't have gotten lost.", why: 'Participio de <i>know</i>: <b>known</b>.' },
          { bad: "He can't have did it alone.", good: "He can't have done it alone.", why: 'Participio de <i>do</i>: <b>done</b>.' },
          { bad: "If she hadn't helped me, I would never finished the thesis.", good: "If she hadn't helped me, I would never have finished the thesis.", why: 'Falta <b>have</b>: <i>would never <b>have</b> finished</i>.' },
          { bad: 'They might have been missed the bus.', good: 'They might have missed the bus.', why: '<i>might have</i> + participio directamente: <b>might have missed</b>. <i>Been</i> sobra (no es pasiva).' },
          { bad: 'I would have called you if I would have had your number.', good: 'I would have called you if I had had your number.', why: 'Otra vez: nada de <i>would</i> con <i>if</i>. <i>If I <b>had had</b></i> (past perfect de <i>have</i>).' },
          { bad: 'We should of checked the address twice.', good: 'We should have checked the address twice.', why: '<s>should of</s> es un error de oído ("should\'ve"). Se escribe <b>should have</b>.' },
          { bad: "If the server hadn't crashed, we would have finish on time.", good: "If the server hadn't crashed, we would have finished on time.", why: 'Después de <i>would have</i>, <b>participio</b>: <i>finished</i>.' },
          { bad: "You shouldn't have to deploy on a Friday. Now everything is broken.", good: "You shouldn't have deployed on a Friday. Now everything is broken.", why: 'Para criticar algo que ya se hizo: <b>shouldn\'t have</b> + participio. <i>Shouldn\'t have to</i> significa "no deberías estar obligado a".' },
        ] },
        { label: 'Ordena el mini-diálogo', type: 'order', eyebrow: 'Condicionales y modales en conversación', title: 'Toca las líneas en el orden correcto', dialogs: [
          ['Ana: Why is the kitchen full of smoke?', 'Luis: I tried to make a soufflé. It was an epic fail.', 'Ana: You must have used the wrong temperature.', "Luis: Probably. If I had read the recipe twice, this wouldn't have happened.", 'Ana: You should have asked me. I make one every Sunday!'],
          ["Paula: The order went to Comas instead of Chorrillos.", 'Marco: You must be joking! How did that happen?', 'Paula: It was my fault. I wrote down the address while I was on another call.', "Marco: You shouldn't have taken two calls at the same time.", "Paula: I know. If I had asked the customer to text me the address, there wouldn't have been a mix-up."],
          ["Diego: Would you have taken the job in Santiago if they had offered more money?", "Rosa: I might have. But I probably wouldn't have left my mother alone.", "Diego: That's fair. And if they had offered remote work?", "Rosa: Then I would have accepted without thinking!", "Diego: You could have asked them, you know. It can't hurt."],
        ] },
        { label: 'Arrepentimiento → condicional', type: 'soft', eyebrow: 'Third conditional · escritura', title: 'Escribe lo que habría pasado', explain: 'Lee lo que pasó de verdad y escribe el tercer condicional: <b>If</b> + sujeto + <b>had / hadn\'t</b> + participio, <b>would / wouldn\'t / might have</b> + participio. Recuerda el espejo: si la realidad es "no probé", la condición imaginada es "si hubiera probado".', missing: 'Falta la estructura: <i>if</i> + <i>had / hadn\'t</i> + participio y <i>would / might have</i> + participio; nunca <i>if I would have</i>', pattern: /^(?!.*\bif (?:i|we|you|he|she|it|they|the \w+|my \w+) (?:would|had have|have|has|was|were|did|didn['’]t)\b)(?:.*\bif\b[^.!?]*\bhad(?:n['’]t)?\b.*\b(?:would|wouldn['’]t|might|could)(?:['’]ve| have)\b|.*\b(?:would|wouldn['’]t|might|could)(?:['’]ve| have)\b.*\bif\b[^.!?]*\bhad(?:n['’]t)?\b)/, items: [
          { h: "Reality: I didn't test the code, so the deployment failed.", a: "If I had tested the code, the deployment wouldn't have failed." },
          { h: 'Reality: I wrote down the wrong address, so the order got lost.', a: "If I hadn't written down the wrong address, the order wouldn't have gotten lost." },
          { h: "Reality: Fleming didn't clean his lab, so he discovered penicillin.", a: "If Fleming had cleaned his lab, he wouldn't have discovered penicillin." },
          { h: "Reality: We didn't read the logs, so we spent two days looking for the bug.", a: "If we had read the logs, we wouldn't have spent two days looking for the bug." },
          { h: "Reality: I took the highway at rush hour, so I arrived late. (resultado posible: might)", a: "If I hadn't taken the highway at rush hour, I might have arrived on time." },
          { h: 'Reality: The customer called late, so I couldn\'t fix the order.', a: 'If the customer had called earlier, I could have fixed the order.' },
          { h: "Reality: I didn't ask for help, so I made a blunder in the demo.", a: "If I had asked for help, I wouldn't have made a blunder in the demo." },
          { h: "Reality: She noticed the phenomenon, so she made a breakthrough.", a: "If she hadn't noticed the phenomenon, she wouldn't have made a breakthrough." },
        ] },
        { label: 'Deduce qué pasó', type: 'soft', eyebrow: 'Modals of past probability · escritura', title: 'Escribe una deducción sobre el pasado', explain: 'Lee las pistas y escribe una frase con <b>must have</b> (seguro), <b>might / may have</b> (quizá), <b>can\'t / couldn\'t have</b> (imposible) o <b>should(n\'t) have</b> (crítica) + <b>participio</b>. La pista en paréntesis te dice el grado.', missing: 'Falta <i>must / might / may / could / couldn\'t / can\'t / should have</i> + participio', pattern: /\b(?:must|might|may|could|couldn['’]t|can['’]t|should|shouldn['’]t)(?:['’]ve| have| not have)\s+(?:been |never )?\w+/, items: [
          { h: "His desk is empty and his coat is gone. (seguro: leave)", a: 'He must have left already.' },
          { h: "She didn't come to the seminar. Maybe she was sick. (quizá: be sick)", a: 'She might have been sick.' },
          { h: "Marco couldn't be the one who broke the build: he was in Cusco. (imposible: break)", a: "Marco couldn't have broken the build." },
          { h: 'The soufflé is flat. The oven was too cold. (crítica: use a hotter oven)', a: 'You should have used a hotter oven.' },
          { h: "The bill says I called Japan, but I never did. (seguro: the company / make a mistake)", a: 'The company must have made a mistake.' },
          { h: 'The empanadas arrived in Comas instead of Chorrillos. (seguro: there / be a mix-up)', a: 'There must have been a mix-up with the addresses.' },
          { h: "You deployed on a Friday at 6 p.m. and it broke. (crítica, negativa: deploy)", a: "You shouldn't have deployed on a Friday." },
          { h: "Nobody answered the phone at the lab. Perhaps they were running an experiment. (quizá: be running)", a: 'They may have been running an experiment.' },
        ] },
        { label: 'Repaso Units 6-9', type: 'mcq', eyebrow: 'Repaso espaciado', title: 'Units 6-9 con vocabulario de la Unit 10', intro: 'Pasiva con modales (Unit 6), reported speech (Unit 7), segundo condicional y <i>wish</i> (Unit 8), permiso, prohibición y obligación en presente y pasado (Unit 9).', items: [
          { blank: 1, q: 'The mistake ___ before the client sees the report.', opts: ['must be corrected', 'must correct', 'must be correct', 'must corrected'], a: 'must be corrected', why: 'Pasiva con modal: modal + <b>be</b> + participio (Unit 6).' },
          { blank: 1, q: 'Penicillin ___ by Alexander Fleming in 1928.', opts: ['was discovered', 'discovered', 'is discovered', 'has discovered'], a: 'was discovered', why: 'Pasiva de pasado: <b>was</b> + participio (Unit 6).' },
          { blank: 1, q: 'She said she ___ the address twice before leaving.', opts: ['had checked', 'has checked', 'checks', 'will check'], a: 'had checked', why: 'Reported speech: pasado → <b>past perfect</b> (Unit 7).' },
          { blank: 1, q: 'He asked me ___ the error on the bill.', opts: ['if I had noticed', 'if had I noticed', 'did I notice', 'that I noticed'], a: 'if I had noticed', why: 'Pregunta indirecta de sí/no: <b>if</b> + orden de afirmación (Unit 7).' },
          { blank: 1, q: 'If I ___ more time, I would carry out my own research.', opts: ['had', 'would have', 'have', 'had had'], a: 'had', why: 'Segundo condicional (presente imaginado): <i>if</i> + <b>pasado simple</b> (Unit 8).' },
          { blank: 1, q: "I wish I ___ that blunder in front of the whole team.", opts: ["hadn't made", "didn't make", "wouldn't make", "haven't made"], a: "hadn't made", why: 'Arrepentimiento del pasado: <i>wish</i> + <b>past perfect</b> (Unit 8).' },
          { blank: 1, q: 'Visitors ___ enter the laboratory without a badge.', opts: ['are not allowed to', 'are not allowed', "don't allow to", 'not allowed to'], a: 'are not allowed to', why: 'Prohibición en presente: <b>be not allowed to</b> + verbo (Unit 9).' },
          { blank: 1, q: 'In 1900, every car ___ have someone walking in front of it with a red flag.', opts: ['was supposed to', 'is supposed to', 'supposed to', 'was supposed'], a: 'was supposed to', why: 'Obligación en el pasado: <b>was / were supposed to</b> (Unit 9).' },
        ] },
      ] },

      /* ================= LISTENING ================= */
      { id: 'listen', label: 'Listening', activities: [
        { label: 'Dictado', type: 'dictation', eyebrow: 'Dictation', title: 'Escucha y escribe exactamente lo que oyes', intro: 'Usa la voz del navegador. Repite las veces que quieras y baja la velocidad si hace falta. Ojo con <i>would have / wouldn\'t have / must have</i>: al hablar suenan "would\'ve, wouldn\'t\'ve, must\'ve", pero se escriben completos.',
          sentences: ["If I had walked into the building, I wouldn't have broken my toe.", "I might never have met my wife if I hadn't broken my toe.", 'Would you have avoided that accident if you had just walked?', 'You could have made it more interesting.', "They simply couldn't have tried harder.", 'She should not have done the act alone.', 'Wanda must have practiced more than Wayne.', "My sister might have gone to work, but I'm not sure.", "You won't believe this, but we delivered the empanadas to the wrong address.", 'Are you ready for this? The deployment failed on a Friday.', "Sorry for the mix-up. It was my fault, and we'll make it right.", 'Anyway, it all worked out in the end.'] },
        { label: 'Diálogo 1 · El viernes negro', type: 'dialog', eyebrow: 'Listening for a story', title: 'Javier cuenta el despliegue que salió mal', intro: 'Javier le cuenta a Karina lo que pasó el viernes en el banco. Fíjate en cómo mantiene el interés y en cómo reacciona ella. Escúchalo entero antes de responder.',
          lines: [['Karina', "You look exhausted. Rough week?"], ['Javier', "You won't believe this, but we deployed the new login on Friday at six."], ['Karina', "Don't tell me you deployed on a Friday evening!"], ['Javier', "I know, I know. We shouldn't have. Anyway, at 6:20 nobody could log in. Not even us."], ['Karina', "You can't be serious!"], ['Javier', "Wait, that's not all! The person with access to the rollback had already left, and his phone was off."], ['Karina', "Let me guess: he was on a plane."], ['Javier', "Worse. He was at his daughter's school play. He must have turned off his phone for the show."], ['Karina', "So what did you do?"], ['Javier', "Are you ready for this? Marco found an old script from 2019 and fixed the problem from his kitchen, with his laptop on top of the fridge."], ['Karina', "That's so crazy! If he hadn't found that script, you would have been there all night."], ['Javier', "Exactly. And if we had tested on Thursday, none of this would have happened. It was partly my fault: I approved the release."], ['Karina', "Well, you made it right in the end. Anyway, lunch is on me today."]],
          questions: [
            { q: 'What was the first mistake, according to Javier?', opts: ['Deploying the new login on a Friday evening', 'Hiring Marco', 'Testing the code on Thursday'], a: 'Deploying the new login on a Friday evening', why: '"We deployed the new login on Friday at six… We shouldn\'t have."' },
            { q: 'Why was the person with rollback access unavailable?', opts: ["He was at his daughter's school play with his phone off", 'He was on a plane', 'He had quit the company'], a: "He was at his daughter's school play with his phone off", why: '"He was at his daughter\'s school play. He must have turned off his phone for the show." Karina supuso <i>on a plane</i> y se equivocó.' },
            { q: 'How was the problem fixed?', opts: ['Marco found an old script and fixed it from his kitchen', 'Javier drove to the office', 'The bank waited until Monday'], a: 'Marco found an old script and fixed it from his kitchen', why: '"Marco found an old script from 2019 and fixed the problem from his kitchen."' },
            { q: 'Which phrase does Javier use to build suspense before the best part?', opts: ['Are you ready for this?', "Don't tell me you…", 'Let me guess'], a: 'Are you ready for this?', why: '<b>Are you ready for this?</b> es una frase para mantener el interés del oyente. Las otras dos son reacciones del oyente (Karina).' },
            { q: 'What does Javier admit at the end?', opts: ['It was partly his fault because he approved the release', 'It was entirely Marco\'s fault', 'Nobody was to blame'], a: 'It was partly his fault because he approved the release', why: '"It was partly my fault: I approved the release."' },
            { q: 'Which sentence is a past unreal conditional?', opts: ['If we had tested on Thursday, none of this would have happened.', 'He must have turned off his phone.', "Don't tell me you deployed on a Friday!"], a: 'If we had tested on Thursday, none of this would have happened.', why: '<i>if</i> + past perfect → <b>would have</b> + participio. <i>Must have turned off</i> es un modal de deducción.' },
          ] },
        { label: 'Diálogo 2 · La factura', type: 'dialog', eyebrow: 'Listening for deductions', title: 'Rosa tiene un cargo extraño en la factura del celular', intro: 'Rosa llama a la operadora. Escucha cómo deducen qué pasó (<i>must have, might have, couldn\'t have</i>) y cómo la empresa arregla las cosas.',
          lines: [['Agent', "Good morning, this is Daniel. How can I help you?"], ['Rosa', "Hi. There's an error on my bill. It says I made a 40-minute call to Japan last Tuesday. I've never called Japan in my life."], ['Agent', "I see. Let me check… Hmm. The call was made at 3 a.m. Could someone else have used your phone?"], ['Rosa', "At 3 a.m.? No. I was asleep and my phone was next to me. It couldn't have been anyone else."], ['Agent', "Then it might have been a technical problem with the roaming system. We had an update that night."], ['Rosa', "So the system must have added the call to the wrong account."], ['Agent', "That's very possible. I'm sorry for the mix-up. We'll correct the error today and you'll see the refund on your next bill."], ['Rosa', "Thank you. Honestly, you should have checked for problems before sending the bills."], ['Agent', "You're right, and I apologize. To make it right, I've also added 5 GB of free data to your plan this month."], ['Rosa', "Oh! Well, that's sweet. Thanks, Daniel."]],
          questions: [
            { q: "What is Rosa's problem?", opts: ['Her bill shows a call to Japan she never made', 'Her phone was stolen at 3 a.m.', 'She wants more data'], a: 'Her bill shows a call to Japan she never made', why: '"It says I made a 40-minute call to Japan… I\'ve never called Japan in my life."' },
            { q: 'Why does Rosa say "It couldn\'t have been anyone else"?', opts: ['Because she was asleep with the phone next to her, so it was impossible', 'Because she lives alone', 'Because she is not sure who used the phone'], a: 'Because she was asleep with the phone next to her, so it was impossible', why: '<b>couldn\'t have been</b> = certeza negativa: era imposible.' },
            { q: 'What explanation does the agent suggest?', opts: ['A technical problem with the roaming system during an update', 'Rosa called Japan while sleeping', 'A friend used her phone'], a: 'A technical problem with the roaming system during an update', why: '"It might have been a technical problem with the roaming system. We had an update that night."' },
            { q: 'Which sentence is a criticism?', opts: ['You should have checked for problems before sending the bills.', 'The system must have added the call to the wrong account.', 'It might have been a technical problem.'], a: 'You should have checked for problems before sending the bills.', why: '<b>should have</b> + participio = crítica de algo que no se hizo.' },
            { q: 'How does the company make it right?', opts: ['A refund on the next bill and 5 GB of free data', 'A new phone', 'A 40-minute free call to Japan'], a: 'A refund on the next bill and 5 GB of free data', why: '"We\'ll correct the error… To make it right, I\'ve also added 5 GB of free data."' },
          ] },
      ] },

      /* ================= SPEAKING ================= */
      { id: 'speak', label: 'Speaking', activities: [
        { label: 'Retos', type: 'speaking', eyebrow: 'Speaking challenge', challenges: [
          { t: 'My epic fail', task: 'Cuenta un error o desastre real (en el trabajo, en el negocio o en la cocina) manteniendo el interés del oyente: You won\'t believe this, but… / Are you ready for this? / But that\'s not all! / Wouldn\'t you know it? Reconoce tu parte de culpa (it was my fault) y cierra con Anyway…', model: "You won't believe this, but last Saturday I had the biggest epic fail of the year. A customer ordered two hundred empanadas for a wedding in Chorrillos. Are you ready for this? I wrote down the address while I was on another call, and I wrote Comas. Comas! We drove forty minutes in the wrong direction. But that's not all! When we finally arrived at the right place, the bride's mother was waiting at the door with her arms crossed. You can imagine. It was completely my fault: I should have asked the customer to text me the address. Wouldn't you know it, the empanadas were still warm, and everybody loved them. We gave them a discount to make it right. Anyway, now I have a rule: no addresses by phone.", tags: ["you won't believe this", 'are you ready for this', "that's not all", 'wouldn\'t you know it', 'you can imagine', 'my fault', 'should have', 'make it right', 'anyway', 'epic fail'] },
          { t: 'If I had known…', task: 'Di tres cosas de tu carrera o tu vida que habrían sido distintas: If I had / hadn\'t…, I would / might have… Explica qué pasó de verdad y qué habría cambiado. Al menos tres terceros condicionales y un might have.', model: "Looking back, there are three moments I think about. First, if I had studied English seriously at university, I would have applied for jobs abroad ten years ago. I didn't, so I stayed in Lima. Second, if I hadn't taken the bank job in 2019, I might never have met the people who helped me start the food business; my first customers were my coworkers. And third, if my wife hadn't pushed me to finish the thesis, I would have given up on it last year. Would I change any of it? I might have studied English earlier, yes. But I wouldn't have changed the bank job. Some mistakes turn out to be discoveries.", tags: ['if i had', "if i hadn't", 'would have', 'might have', 'would never have', 'looking back', "wouldn't have changed"] },
          { t: 'What must have happened?', task: 'Llegas a la oficina a las 9: las luces están encendidas, hay cafés fríos en todas las mesas, la pizarra está llena de diagramas y no hay nadie. Deduce qué pasó con must have, might have, can\'t / couldn\'t have y critica con should have. Al menos seis deducciones.', model: "OK, let's see. The lights are on and there are cold coffees everywhere, so people must have been here very early, maybe all night. The whiteboard is full of diagrams of the payment system. There must have been an incident with payments. They can't have gone home; their bags are still here. They might have gone to the data center, or they may have gone out for breakfast after fixing it. Wait, there's a pizza box from 2 a.m. They must have worked until at least two. Honestly, someone should have called me; I know that system better than anyone. And they shouldn't have deployed the payment update yesterday. I told them it couldn't have been tested properly in one afternoon.", tags: ['must have', 'might have', 'may have', "can't have", "couldn't have", 'should have', "shouldn't have", 'incident'] },
          { t: 'A discovery in my thesis', task: 'Habla de un descubrimiento o avance (en la tesis, en el trabajo, en el negocio) usando al menos cinco colocaciones: carry out research, face a challenge, gain knowledge, notice a phenomenon, make a connection, provide insight, make a breakthrough, provide a solution.', model: "For my thesis I'm carrying out research on why small businesses abandon digital payment apps. At the beginning I faced a big challenge: nobody wanted to answer my survey. So I did something different. I used my own food business as a case study and interviewed my customers. I noticed a phenomenon very quickly: people didn't stop using the apps because of fees, but because of confusion when a payment failed. That provided real insight. Then I made a connection with the bank's data: the same pattern appeared there. That was my small breakthrough. I haven't provided a complete solution yet, but I've gained a lot of knowledge about how people react when technology makes a mistake. They don't want an explanation. They want someone to make it right.", tags: ['carrying out research', 'faced a challenge', 'noticed a phenomenon', 'provided insight', 'made a connection', 'breakthrough', 'solution', 'gained', 'knowledge'] },
          { t: 'Making it right', task: 'Llama a un cliente al que le llegó el pedido equivocado. Pide disculpas sin culpar a nadie (it was my fault / there was a mix-up / a misunderstanding), explica qué habrías hecho distinto (I should have…), ofrece una solución (fix the problem / make it right) y cierra con calidez.', model: "Hi, Mrs. Torres, this is Aldo from La Consentida. I'm calling about your order. I'm really sorry: there was a mix-up in the kitchen and you received the chicken empanadas instead of the vegetarian ones. It was completely my fault; I should have checked the boxes before the driver left. I know your guests are vegetarian, so this isn't a small mistake. Here's what I'd like to do to make it right: a driver is already on his way with thirty vegetarian empanadas, free of charge, and he'll be there in twenty minutes. You can keep the chicken ones, of course. And your next order is on us. Again, I'm so sorry for the confusion. If there's anything else I can do to fix this, please tell me.", tags: ['mix-up', 'my fault', 'should have', 'make it right', 'free of charge', 'confusion', 'fix', "i'm really sorry", 'mistake'] },
        ] },
        { label: 'Pronunciación', type: 'stress', eyebrow: 'Pronunciación · contracciones y sílaba tónica', title: '"would\'ve, shouldn\'t\'ve" y BREAKthrough / pheNOmenon', intro: 'Primero las contracciones de los modales de pasado: <i>would have</i> suena "wúd-av", <i>wouldn\'t have</i> "wúd-nt-av", <i>should have</i> "shúd-av", <i>couldn\'t have</i> "cúd-nt-av", <i>must have</i> "mást-av", <i>might have</i> "mait-av". El <i>have</i> casi desaparece: /əv/. Después, la sílaba fuerte (en MAYÚSCULAS) del vocabulario. Escucha y repite.',
          pairs: [["would have → \"wúd-av\"", 'I would have called you.'], ["wouldn't have → \"wúd-nt-av\"", "It wouldn't have happened."], ["should have → \"shúd-av\"", 'You should have told me.'], ["shouldn't have → \"shúd-nt-av\"", "We shouldn't have deployed on a Friday."], ["couldn't have → \"cúd-nt-av\"", "They couldn't have tried harder."], ["must have → \"mást-av\"", 'She must have forgotten.'], ["might have → \"mait-av\"", 'He might have taken the highway.'], ["If I'd known → \"if aid nóun\"", "If I'd known, I would have brought an umbrella."], ['Pregunta completa', 'Would you have accepted the job if they had offered you more money?'], ['BREAKthrough', 'breakthrough'], ['disCOvery · disCOver', 'discovery, discover'], ['pheNOmenon', 'phenomenon'], ['REsearch (n.) · reSEARCH (v.)', 'research'], ['BLUNder · conFUsion', 'blunder, confusion'], ['misunderSTANding', 'misunderstanding'], ['MIX-up · Epic FAIL', 'a mix-up, an epic fail'], ['Entonación ascendente', 'Are you ready for this?'], ['Énfasis en la sorpresa', "You can't be SErious! You must be JOking!"], ['Frase completa', "You won't believe this, but if I had checked the address, we wouldn't have driven to Comas. Anyway, it all worked out."]] },
      ] },

      /* ================= READING ================= */
      { id: 'read', label: 'Reading', activities: [
        { type: 'reading', eyebrow: 'Reading for main ideas · inferring meaning', title: 'Happy accidents', intro: 'Lee una vez para la idea general y otra fijándote en los terceros condicionales y los modales de pasado. Las palabras en amarillo se preguntan después: intenta deducirlas por el contexto.',
          paragraphs: [
            "Some of the most useful things in your kitchen and your medicine cabinet exist because somebody made a mistake and then paid attention. Historians of science call these happy accidents \"serendipity\", but the stories show something more specific: the discoverers noticed a phenomenon that others had ignored, and they made a connection that nobody had made before.",
            "In 1928, Alexander Fleming went on vacation and left a pile of dirty dishes in his London laboratory. When he came back, one of them was <b>contaminated</b> with mold, and around the mold the bacteria had died. A tidier scientist would have thrown the dish away. Fleming didn't. If he had cleaned up before his trip, he wouldn't have seen the effect, and penicillin might have waited another twenty years.",
            "Two decades later, an engineer named Percy Spencer was testing radar equipment when he noticed that the chocolate bar in his pocket had <b>melted</b>. He could have blamed the heat of the room; instead, he carried out a few experiments with popcorn and an egg, and the microwave oven was born. The Post-it note followed a similar path: in 1968, Spencer Silver was trying to create a super-strong glue and produced a <b>feeble</b> one that barely held two sheets of paper together. For years it was considered a failure, until a colleague, Art Fry, made the connection with the paper bookmarks that kept falling out of his hymn book.",
            "None of these people were trying to make the discovery they are famous for. What they shared was a habit: when something went wrong, they asked why before they fixed the problem. It is tempting to say that they were lucky, and they were. But hundreds of other scientists must have seen moldy dishes and melted chocolate, and they simply cleaned up. You don't <b>stumble upon</b> a breakthrough by accident. You stumble upon it because, when the accident happens, you are paying attention.",
          ],
          main: [
            { q: 'Accidental discoveries happen when someone notices what others ignore.', opts: ['1', '2', '3', '4'], a: '1', why: 'Párrafo 1: <i>the discoverers noticed a phenomenon that others had ignored, and they made a connection</i>.' },
            { q: 'A scientist who did not clean up discovered an important medicine.', opts: ['1', '2', '3', '4'], a: '2', why: 'Párrafo 2: Fleming, la penicilina y el tercer condicional <i>If he had cleaned up… he wouldn\'t have seen the effect</i>.' },
            { q: 'Two everyday objects were born from a melted snack and a glue that did not work.', opts: ['1', '2', '3', '4'], a: '3', why: 'Párrafo 3: el microondas (chocolate derretido) y el Post-it (pegamento débil).' },
            { q: 'Luck matters, but the real difference is asking why when something goes wrong.', opts: ['1', '2', '3', '4'], a: '4', why: 'Párrafo 4: <i>when something went wrong, they asked why before they fixed the problem… you are paying attention</i>.' },
          ],
          infer: [
            { q: '<b>contaminated</b> (paragraph 2)', opts: ['made dirty or impure by something unwanted', 'cleaned very carefully', 'broken into pieces'], a: 'made dirty or impure by something unwanted', why: 'Era un plato sucio (<i>dirty dishes</i>) en el que había crecido moho (<i>mold</i>).' },
            { q: '<b>melted</b> (paragraph 3)', opts: ['changed from solid to liquid because of heat', 'disappeared from his pocket', 'became very cold'], a: 'changed from solid to liquid because of heat', why: 'Una barra de chocolate junto a un equipo de radar que calienta: se derritió. Por eso <i>he could have blamed the heat</i>.' },
            { q: '<b>feeble</b> (paragraph 3)', opts: ['weak', 'extremely strong', 'expensive'], a: 'weak', why: 'Buscaba un pegamento <i>super-strong</i> y le salió uno que <i>barely held two sheets of paper together</i>: débil.' },
            { q: '<b>stumble upon</b> (paragraph 4)', opts: ['find something by chance', 'look for something for years', 'fall down and get hurt'], a: 'find something by chance', why: 'Se contrasta con <i>by accident</i> y <i>paying attention</i>: encontrar algo sin buscarlo.' },
          ],
          think: '¿Cuál ha sido tu "happy accident" en el trabajo o en el negocio: un error que terminó enseñándote algo? Escribe tres frases: una con <i>If I hadn\'t…, I wouldn\'t have…</i>, una con <i>I must have / might have…</i> y una con una colocación de la unidad (<i>notice a phenomenon, make a connection, provide insight</i>).' },
      ] },

      /* ================= WRITING ================= */
      { id: 'write', label: 'Writing', activities: [
        { label: 'Contar un error', type: 'notes', eyebrow: 'Writing skill · telling the story of a mistake', title: 'Cómo se estructura la historia de un error (y su lección)', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>A · Estructura</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Gancho:</b> You won't believe this, but… / Are you ready for this?</li><li><b>Contexto breve:</b> Last Saturday, a customer ordered… / It was a Friday at 6 p.m. and…</li><li><b>El error, con su nombre:</b> I made a blunder / There was a mix-up / It was my fault / I got the address wrong.</li><li><b>Sube la tensión:</b> But that's not all! / Wouldn't you know it? / You can imagine!</li><li><b>Qué habría pasado:</b> If I had checked…, I wouldn't have… / Somebody must have…</li><li><b>Cómo lo arreglaste:</b> We fixed the problem / We made it right by…</li><li><b>La lección:</b> I should have… / Anyway, now I always…</li></ul></div>
          <div><h3>B · Frases útiles</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><i>It was partly my fault.</i> (reconoces sin cargar con todo)</li><li><i>I'm not blaming anyone, but…</i></li><li><i>There must have been a misunderstanding about the date.</i></li><li><i>I should have double-checked.</i> / <i>I shouldn't have assumed.</i></li><li><i>If I could go back, I would have asked.</i></li><li><i>Lesson learned: no addresses by phone.</i></li><li><i>Anyway, it all worked out in the end.</i></li></ul></div>
          <div class="hint small"><b>Ojo:</b> <b>make</b> a mistake, nunca <s>do a mistake</s>. · <b>my fault</b>, no <s>my blame</s>; <b>blame someone for</b> something, no <s>blame of</s>. · <i>research</i> es incontable: <i>some research</i>, nunca <s>a research</s>. · <b>get</b> something <b>wrong</b>: <i>I got the date wrong</i>, no <s>I got wrong the date</s>. · En un correo formal escribe <b>should have</b>, nunca <i>should've</i> ni <s>should of</s>. · <b>Anyway</b> (sin -s) para cambiar o retomar el tema.</div></div>` },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · vocabulario y narración', title: 'Reescribe la frase corrigiendo el error', intro: 'Errores típicos al contar un error y al hablar de ciencia. Un solo error por frase.', items: [
          { bad: 'It was fault of mine, not yours.', good: 'It was my fault, not yours.', why: 'La fórmula fija es <b>my / your / his fault</b>.' },
          { bad: 'I did a mistake in the address.', good: 'I made a mistake in the address.', why: '<b>make a mistake</b>. <i>Do</i> no se combina con <i>mistake</i>.' },
          { bad: 'Sorry for the mix-up. We will do it right.', good: 'Sorry for the mix-up. We will make it right.', why: '<b>make it right</b> = compensar / arreglar las cosas.' },
          { bad: 'The researchers did a breakthrough last year.', good: 'The researchers made a breakthrough last year.', why: '<b>make a breakthrough</b>.' },
          { bad: 'She blamed me of the accident.', good: 'She blamed me for the accident.', why: '<b>blame someone for</b> something.' },
          { bad: 'We are carrying out a research about sea life.', good: 'We are carrying out research about sea life.', why: '<i>research</i> es incontable: sin <i>a</i>. (<i>A study</i> sí es contable.)' },
          { bad: 'I got wrong the answer.', good: 'I got the answer wrong.', why: 'Orden: <b>get</b> + objeto + <b>wrong</b>.' },
          { bad: 'There was a big misunderstood about the date.', good: 'There was a big misunderstanding about the date.', why: 'El sustantivo es <b>misunderstanding</b>; <i>misunderstood</i> es el participio.' },
          { bad: "You don't will believe this, but the order went to Comas.", good: "You won't believe this, but the order went to Comas.", why: 'Negativa de <i>will</i>: <b>won\'t</b>. Frase fija: <i>You won\'t believe this, but…</i>' },
          { bad: "Don't tell me that you did forget the password!", good: "Don't tell me you forgot the password!", why: 'Pasado simple normal: <b>you forgot</b>. <i>Did</i> solo en preguntas y negativas (o para enfatizar, con otra entonación).' },
          { bad: 'The city provided a solution adding more bins.', good: 'The city provided a solution by adding more bins.', why: 'El medio se expresa con <b>by</b> + -ing.' },
          { bad: 'Anyways, it all worked out in the end.', good: 'Anyway, it all worked out in the end.', why: '<b>Anyway</b>, sin -s, es la forma estándar (<i>anyways</i> es muy coloquial y suena descuidado).' },
        ] },
        { label: 'Engancha al oyente', type: 'soft', eyebrow: 'Keeping your listener engaged · escritura', title: 'Añade un gancho a la frase plana', explain: 'Cada frase cuenta un hecho sin emoción. Reescríbela añadiendo una fórmula de la unidad para mantener el interés: <b>You won\'t believe this, but…</b> · <b>Are you ready for this?</b> · <b>But that\'s not all!</b> · <b>Wouldn\'t you know it?</b> · <b>You can imagine!</b> · <b>You know what?</b> · <b>Isn\'t that amazing?</b> · o retoma el hilo con <b>Anyway, …</b>', missing: 'Falta una fórmula para mantener el interés: <i>You won\'t believe this, but… · Are you ready for this? · But that\'s not all! · Wouldn\'t you know it? · You can imagine! · You know what? · Isn\'t that amazing? · Anyway…</i>', pattern: /\b(?:are you ready for this|but that['’]s not all|that['’]s not all|isn['’]t that (?:amazing|crazy|funny|strange|great)|wouldn['’]t you know it|you can imagine|you know what|you won['’]t believe (?:this|it|what)|anyway)\b/, items: [
          { h: '"The order went to the wrong address." (gancho inicial)', a: "You won't believe this, but the order went to the wrong address." },
          { h: '"We deployed on a Friday at 6 p.m." (prepara al oyente)', a: 'Are you ready for this? We deployed on a Friday at 6 p.m.' },
          { h: '"The person with rollback access had his phone off." (sube la tensión: no es todo)', a: "But that's not all! The person with rollback access had his phone off." },
          { h: '"It started raining the moment we opened the boxes." (mala suerte típica)', a: "Wouldn't you know it? It started raining the moment we opened the boxes." },
          { h: '"The bride\'s mother was waiting at the door." (deja que el oyente imagine)', a: "The bride's mother was waiting at the door. You can imagine!" },
          { h: '"The empanadas were still warm." (sorpresa positiva)', a: 'You know what? The empanadas were still warm.' },
          { h: '"Fleming found penicillin because he didn\'t clean his lab." (pide la reacción)', a: "Fleming found penicillin because he didn't clean his lab. Isn't that amazing?" },
          { h: '"Now I never take addresses by phone." (retoma el hilo y cierra)', a: 'Anyway, now I never take addresses by phone.' },
        ] },
        { label: 'Escribe tu historia', type: 'comment', eyebrow: 'Writing task', title: 'La historia de un error (y lo que habrías hecho distinto)', intro: 'Escribe 100-150 palabras contando un error real o inventado (un despliegue, un pedido, un viaje). Mantén el interés con las frases de la unidad, ponle nombre al error (<i>blunder, mix-up, my fault…</i>), imagina qué habría pasado (tercer condicional), deduce o critica con un modal de pasado y cierra con la lección. La checklist se marca sola al analizar el texto.', placeholder: "You won't believe this, but last Friday… It was my fault: I should have… If I had…, we wouldn't have… Anyway, lesson learned: …", min: 100, max: 150, need: 4, checks: [
          { label: 'Uso un tercer condicional completo (<i>if</i> + <i>had</i> + participio … <i>would / might have</i> + participio)', re: /\bif\b[^.?!]*\bhad(?:n['’]t)?\b[^.?!]*\b(?:would|wouldn['’]t|might|could)(?:['’]ve| have)\b|\b(?:would|wouldn['’]t|might|could)(?:['’]ve| have)\b[^.?!]*\bif\b[^.?!]*\bhad(?:n['’]t)?\b/ },
          { label: 'Uso un modal de probabilidad o crítica en pasado (<i>must / might / may / could / couldn\'t / should(n\'t) have</i> + participio)', re: /\b(?:must|might|may|could|couldn['’]t|can['’]t|should|shouldn['’]t)(?:['’]ve| have| not have) (?:been |never )?\w+/ },
          { label: 'Pongo nombre al error (<i>blunder, mix-up, misunderstanding, confusion, my fault, epic fail, made a mistake, got … wrong</i>)', re: /\b(blunder|epic fail|mix-up|mixup|misunderstanding|confusion|fault|blame|made (?:a|an|the|another) (?:big |huge |stupid |serious )?(?:mistake|error|blunder)|got (?:it|something|the \w+|that) wrong)\b/ },
          { label: 'Mantengo el interés (<i>You won\'t believe this / Are you ready for this? / But that\'s not all! / Wouldn\'t you know it? / You can imagine! / You know what?</i>)', re: /\b(?:you won['’]t believe (?:this|it|what)|are you ready for this|that['’]s not all|wouldn['’]t you know it|you can imagine|you know what|isn['’]t that (?:amazing|crazy|funny|strange))\b/ },
          { label: 'Digo cómo lo arreglé (<i>fixed the problem / corrected the mistake / made it right / provided a solution</i>)', re: /\b(?:fix(?:ed)? (?:the|that|this) (?:problem|issue|bug)|correct(?:ed)? (?:the|my|that) (?:mistake|error)|ma(?:ke|de) (?:it|things) right|provid(?:e|ed) a solution|solved (?:the|it))\b/ },
          { label: 'Cierro con la lección o retomo el hilo (<i>Anyway… / Lesson learned / Now I always… / Never again</i>)', re: /\b(?:anyway|lesson learned|now i (?:always|never)|never again|from now on|the lesson (?:is|was))\b/ },
        ] },
        { label: 'Arreglar las cosas', type: 'comment', eyebrow: 'Writing task · short', title: 'Mensaje a un cliente tras un error', intro: 'Escribe 50-90 palabras a un cliente que recibió el pedido equivocado (o a un usuario afectado por un fallo del sistema). Reconoce el error sin culpar a otros, explica brevemente qué pasó (<i>there was a mix-up / a misunderstanding</i>), di qué deberías haber hecho (<i>should have</i>) y ofrece cómo lo vas a arreglar (<i>make it right</i>).', placeholder: "Dear Mrs. Torres, I'm writing to apologize… There was a mix-up… It was my fault: I should have… To make it right, …", min: 50, max: 90, need: 3, checks: [
          { label: 'Pido disculpas y reconozco la responsabilidad (<i>I\'m sorry / I apologize / my fault / our mistake</i>)', re: /\b(?:i['’]m (?:so |really |very |truly )?sorry|i apologize|we apologize|my fault|our fault|our mistake|my mistake|we made a mistake|i made a mistake)\b/ },
          { label: 'Explico qué pasó con una palabra de la unidad (<i>mix-up, misunderstanding, confusion, error, blunder</i>)', re: /\b(?:mix-up|mixup|misunderstanding|confusion|error|blunder|got (?:it|the \w+) wrong)\b/ },
          { label: 'Digo qué debería haber hecho (<i>should have / shouldn\'t have</i> + participio)', re: /\b(?:should|shouldn['’]t)(?:['’]ve| have| not have) \w+/ },
          { label: 'Ofrezco una solución concreta (<i>to make it right / fix the problem / a refund / a new order / free of charge</i>)', re: /\b(?:make (?:it|this|things) right|fix (?:the|this) (?:problem|issue)|refund|a new order|free of charge|on us|discount|replace)\b/ },
          { label: 'Cierro con calidez (<i>Thank you for your patience / Please let me know / Again, I\'m sorry</i>)', re: /\b(?:thank you for your (?:patience|understanding)|please let me know|again, (?:i['’]m|we['’]re) (?:so |really )?sorry|once again|if there['’]s anything else|best regards|kind regards|sincerely)\b/ },
        ] },
      ] },

      /* ================= SOCIAL ENGLISH ================= */
      { id: 'social', label: 'Social English', activities: [
        { label: 'Frases', type: 'notes', eyebrow: 'Functional language · Lesson 3', title: 'Mantener el interés y mostrar que escuchas', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>Keeping your listener engaged</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Are you ready for this?</b> (antes de lo mejor)</li><li><b>But that's not all!</b> (hay más)</li><li><b>Isn't that amazing?</b> (pide la reacción)</li><li><b>Wouldn't you know it?</b> (mala suerte típica, ironía)</li><li><b>You can imagine!</b> (deja que el otro complete)</li><li><b>You know what?</b> (giro inesperado)</li><li><b>You won't believe this, but…</b> (gancho inicial)</li></ul></div>
          <div><h3>Showing you're interested in a story</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Don't tell me you…!</b> (adivinas lo peor)</li><li><b>Let me guess – you…!</b> (adivinas)</li><li><b>That's (so) funny / strange / great / crazy / awful / sweet!</b></li><li><b>You can't be serious!</b></li><li><b>You must be joking!</b></li></ul></div>
          <div><h3>Cuándo usar cada una</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li>Quien <b>cuenta</b> usa las de la izquierda: son preguntas retóricas o avisos de que viene algo bueno.</li><li>Quien <b>escucha</b> usa las de la derecha: reacciona sin interrumpir el hilo.</li><li><i>That's so + adjetivo</i> es la más flexible: elige el adjetivo según la historia (<i>awful</i> para una desgracia, <i>sweet</i> para algo tierno, <i>crazy</i> para lo increíble).</li><li><i>You can't be serious!</i> y <i>You must be joking!</i> no acusan de mentir: expresan sorpresa.</li></ul></div>
          <div><h3>Responding as the storyteller</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>I know, right?</b></li><li><b>I'm serious! / I'm not joking.</b></li><li><b>Exactly! And wait, there's more.</b></li><li><b>Anyway, …</b> (y sigues)</li></ul></div>
          <div class="hint small"><b>Insider English: "Anyway"</b><br>En conversación, <b>anyway</b> sirve para <b>cambiar de tema</b>, <b>volver al tema</b> después de una interrupción o <b>ir al grano</b>: <i>"I guess they felt sorry for us. <b>Anyway</b>, it was all so nice, we decided to go there again next summer!"</i> · <i>"Sorry, where was I? <b>Anyway</b>, so the order arrives in Comas…"</i> · <i>"<b>Anyway</b>, lunch? I'm paying."</i> Es la palabra que cierra una digresión. Sin -s: <s>anyways</s> suena descuidado. Combina bien con <i>As I was saying…</i> y <i>Where was I?</i> de la Unit 7.</div></div>` },
        { label: 'Ordena el diálogo', type: 'order', eyebrow: 'Ordena el diálogo', title: 'Toca las líneas en el orden correcto', dialogs: [
          ["Sofía: You won't believe this, but I found my old laptop in a box at my mom's house.", "Tomás: Let me guess: it didn't turn on.", "Sofía: Wrong! It did. And are you ready for this? It still had my thesis from 2015.", "Tomás: You can't be serious! You told me you had lost it forever.", "Sofía: I know, right? I must have made a backup and forgotten about it.", "Tomás: That's so great! Anyway, are you going to read it?"],
          ["Nico: The hotel in Cusco was tiny, but the staff was really friendly.", "Bea: Friendly how?", "Nico: Wouldn't you know it? The first night the heating broke.", "Bea: Oh no. Don't tell me you slept in your coat!", "Nico: Almost. But that's not all! At midnight the manager knocked on the door with a thermos of hot chocolate and three blankets.", "Bea: That's so sweet! You must have been freezing, though."],
          ["Carla: How was the deployment?", "Hugo: You know what? It was fine. For about twenty minutes.", "Carla: Twenty minutes? You must be joking!", "Hugo: I'm serious. Then the login stopped working. You can imagine the Slack channel.", "Carla: That's awful. Was it your fault?", "Hugo: Partly. We should have tested on Thursday. Anyway, Marco fixed it from his kitchen, so it all worked out."],
        ] },
        { label: 'Respuesta rápida', type: 'mcq', eyebrow: 'Respuesta rápida', title: '¿Qué dices?', items: [
          { q: 'Vas a contar algo increíble que te pasó. Empiezas con un gancho.', opts: ["You won't believe this, but I found my old laptop.", "Don't tell me you found your old laptop!", "You must be joking!"], a: "You won't believe this, but I found my old laptop.", why: '<b>You won\'t believe this, but…</b> es el gancho del que cuenta. Las otras dos son reacciones del oyente.' },
          { q: 'Llegas a la mejor parte de la historia y quieres que tu amigo preste atención.', opts: ['Are you ready for this?', 'Let me guess!', "That's so funny!"], a: 'Are you ready for this?', why: '<b>Are you ready for this?</b> = prepárate para lo que viene.' },
          { q: 'Ya contaste un desastre, pero hubo otro después.', opts: ["But that's not all!", 'Anyway, lunch?', "You can't be serious!"], a: "But that's not all!", why: '<b>But that\'s not all!</b> = y hay más.' },
          { q: 'Tu amiga te cuenta que desplegó un viernes. Adivinas (con horror) lo que pasó.', opts: ["Don't tell me it broke!", "Isn't that amazing?", 'You can imagine!'], a: "Don't tell me it broke!", why: '<b>Don\'t tell me…!</b> = el oyente adivina lo peor. Las otras dos las dice quien cuenta.' },
          { q: 'Tu amigo te dice que el hotel les regaló una habitación mejor. Expresas sorpresa positiva.', opts: ["That's so great!", "That's awful!", "Don't tell me you complained!"], a: "That's so great!", why: '<b>That\'s so + adjetivo</b>: elige el adjetivo según la historia. Buena noticia → <i>great</i>.' },
          { q: 'Te cuentan algo tan increíble que parece broma.', opts: ['You must be joking!', 'Wouldn\'t you know it?', 'You know what?'], a: 'You must be joking!', why: '<b>You must be joking!</b> / <b>You can\'t be serious!</b> = sorpresa del oyente, no acusación.' },
          { q: 'Cuentas que, justo cuando abriste las cajas, empezó a llover. Mala suerte típica.', opts: ["Wouldn't you know it?", "Let me guess!", "That's so sweet!"], a: "Wouldn't you know it?", why: '<b>Wouldn\'t you know it?</b> = "cómo no", ironía ante la mala suerte.' },
          { q: 'Prefieres no describir la cara de la suegra: que tu amigo se la imagine.', opts: ['You can imagine!', 'Are you ready for this?', "Don't tell me!"], a: 'You can imagine!', why: '<b>You can imagine!</b> deja que el oyente complete la escena.' },
          { q: 'Te desviaste hablando del clima y quieres volver a la historia.', opts: ['Anyway, so the order arrives in Comas…', "But that's not all!", "Isn't that amazing?"], a: 'Anyway, so the order arrives in Comas…', why: '<b>Anyway</b> = retomar el hilo (Insider English).' },
          { q: 'Tu amiga empieza a contar que perdió el pasaporte. Intentas adivinar el final.', opts: ['Let me guess: you had to go to the consulate.', 'You can imagine!', 'Are you ready for this?'], a: 'Let me guess: you had to go to the consulate.', why: '<b>Let me guess – you…!</b> = el oyente adivina.' },
          { q: 'Tu amigo dice "You must be joking!" y tú quieres confirmar que es verdad.', opts: ["I'm serious! And wait, there's more.", 'You must be joking!', 'Let me guess.'], a: "I'm serious! And wait, there's more.", why: 'El que cuenta confirma: <b>I\'m serious!</b> / <i>I\'m not joking</i>, y sigue.' },
          { q: 'Tu compañera cuenta que su sobrino de cinco años le dejó una nota de disculpa escrita a mano.', opts: ["That's so sweet!", "That's so awful!", "You don't want to do that!"], a: "That's so sweet!", why: 'Algo tierno → <b>That\'s so sweet!</b>' },
        ] },
        { label: 'Reacciona como oyente', type: 'soft', eyebrow: 'Showing you\'re interested · escritura', title: 'Responde a cada parte de la historia', explain: 'Alguien te cuenta una historia frase a frase. Escribe tu reacción con una fórmula de la unidad: <b>Don\'t tell me you…!</b> · <b>Let me guess – you…!</b> · <b>That\'s so funny / strange / crazy / awful / sweet!</b> · <b>You can\'t be serious!</b> · <b>You must be joking!</b> Puedes añadir una deducción con <i>must have</i>.', missing: 'Falta una reacción de oyente: <i>Don\'t tell me… · Let me guess… · That\'s so… · You can\'t be serious! · You must be joking!</i>', pattern: /\b(?:don['’]t tell me|let me guess|that['’]s (?:so |really )?(?:funny|strange|great|crazy|awful|sweet|terrible|amazing|wild|weird)|you can['’]t be serious|you must be joking|no way)\b/, items: [
          { h: '"So we deployed the new login on Friday at six…"', a: "Don't tell me you deployed on a Friday evening!" },
          { h: '"…and the only person with rollback access had already left."', a: 'Let me guess: his phone was off.' },
          { h: '"Marco fixed it from his kitchen, with the laptop on top of the fridge."', a: "That's so crazy! He must have been desperate." },
          { h: '"The hotel upgraded us to a suite for free."', a: "You can't be serious! That's so great!" },
          { h: '"My nephew wrote me an apology note in crayons."', a: "That's so sweet!" },
          { h: '"The airline sent my suitcase to Japan. Twice."', a: 'You must be joking! That\'s awful.' },
          { h: '"I found my 2015 thesis on an old laptop in my mom\'s garage."', a: "No way! You must have made a backup and forgotten." },
          { h: '"And then it started raining the moment we opened the boxes."', a: "That's so typical! Don't tell me the empanadas got wet." },
        ] },
        { label: 'Role-play', type: 'roleplay', eyebrow: 'Role-play con ramas', title: 'Las 200 empanadas', intro: 'Dani te pregunta por el fin de semana y tú tienes una historia: el pedido de 200 empanadas que fue a la dirección equivocada el mismo día del despliegue. Cuéntala manteniendo el interés, reconoce tu parte de culpa y cierra con elegancia. Si culpas a la clienta o pierdes el hilo, Dani se aburre.', scenes: [
          { t: 'Las 200 empanadas', you: 'Aldo, el que cuenta la historia', partner: 'Dani', role: 'tu amigo, curioso y bromista', goal: 'Cuenta el desastre del sábado con las frases para mantener el interés, reconoce el error con el vocabulario de la unidad (my fault, mix-up, should have) y remata con un tercer condicional y un Anyway.', start: 'a', nodes: {
            a: { say: "Hey! How was the weekend? You look tired.", opts: [
              { t: "You won't believe this, but I had the biggest epic fail of the year on Saturday.", ok: 2, why: "Gancho perfecto: <b>You won't believe this, but…</b> + <b>epic fail</b>. Dani ya quiere saber más.", next: 'b' },
              { t: "It was crazy. Something went really wrong with an order on Saturday.", ok: 1, why: "Correcta y natural, pero sin gancho. Con <b>You won't believe this, but…</b> enganchas desde la primera frase.", next: 'b' },
              { t: "You don't will believe this, but I had an epic fail on Saturday.", ok: 0, why: "La negativa de <i>will</i> es <b>won't</b>: <i>You <b>won't</b> believe this</i>.", next: 'b' },
            ] },
            b: { say: "An epic fail? OK, now I need to know. What happened?", opts: [
              { t: "Are you ready for this? A customer ordered 200 empanadas for a wedding, and I wrote down the wrong address.", ok: 2, why: "<b>Are you ready for this?</b> prepara al oyente para lo bueno, y <b>wrote down the wrong address</b> es la colocación natural.", next: 'c' },
              { t: "A customer ordered 200 empanadas for a wedding, and I wrote down the wrong address.", ok: 1, why: "Correcta. Le falta el aviso (<i>Are you ready for this?</i>) que convierte un hecho en una historia.", next: 'c' },
              { t: "A customer ordered 200 empanadas and I writed the address wrong.", ok: 0, why: "<i>Write</i> es irregular: <b>wrote</b>. Y el orden natural: <i>wrote down the wrong address</i> o <i>got the address wrong</i>.", next: 'c' },
            ] },
            c: { say: "No! Don't tell me you delivered them to the wrong place.", opts: [
              { t: "Yes. But that's not all! The real address was in Chorrillos, and we were in Comas.", ok: 2, why: "<b>But that's not all!</b> sube la tensión justo cuando Dani cree que ya sabe el final.", next: 'd' },
              { t: "Yes, we did. The real address was in Chorrillos, and we were in Comas.", ok: 1, why: "Correcta, pero plana. Aquí la unidad te da <b>But that's not all!</b> para seguir enganchando.", next: 'd' },
              { t: "Yes. It was the fault of the customer; she talks too fast.", ok: 0, why: "Culpar al cliente rompe la historia (y la simpatía). Además la forma es <b>the customer's fault</b>, no <i>the fault of the customer</i>.", next: 'c2' },
            ] },
            c2: { say: "The customer's fault? Really, Aldo?", opts: [
              { t: "OK, no. It was my fault. I should have double-checked the address.", ok: 2, why: "Rectificas con las dos fórmulas de la unidad: <b>It was my fault</b> y <b>I should have</b> + participio.", next: 'd' },
              { t: "Well, partly mine. I should have checked it twice.", ok: 1, why: "Correcta: <b>partly my fault</b> + <b>should have checked</b>. Un poco a regañadientes, pero funciona.", next: 'd' },
              { t: "Yes! If she would have written it clearly, this wouldn't have happened.", ok: 0, why: "Doble problema: sigues culpándola y <s>if she would have</s> es el error clásico: <b>If she had written</b>. Dani pierde el interés.", next: 'fail' },
            ] },
            d: { say: "So what did you do? You can't just leave a wedding without food!", opts: [
              { t: "You can imagine! We drove across the city with 200 empanadas. And you know what? We arrived before the party started.", ok: 2, why: "<b>You can imagine!</b> deja que Dani complete la escena y <b>You know what?</b> anuncia el giro. Ritmo de narrador.", next: 'e' },
              { t: "We drove across the city with 200 empanadas and arrived before the party started.", ok: 1, why: "Correcta y clara. Sin las fórmulas, suena a informe más que a historia.", next: 'e' },
              { t: "We drived across the city and arrive before the party.", ok: 0, why: "<i>Drive</i> es irregular: <b>drove</b>; y la historia va en pasado: <b>arrived</b>.", next: 'e' },
            ] },
            e: { say: "That's so funny! Wait. Wasn't Saturday also your production release at the bank?", opts: [
              { t: "Wouldn't you know it? Yes. While I was driving, my phone rang: the deployment had failed.", ok: 2, why: "<b>Wouldn't you know it?</b> es la fórmula de la mala suerte típica, y el past perfect (<i>had failed</i>) ordena los hechos.", next: 'f' },
              { t: "Yes. While I was driving, my phone rang. The deployment had failed.", ok: 1, why: "Correcta, con buen uso del pasado. Le falta el guiño irónico de <b>Wouldn't you know it?</b>", next: 'f' },
              { t: "Yes. The deployment was failed while I drove.", ok: 0, why: "<i>Fail</i> no va en pasiva aquí: <b>the deployment failed</b> / <b>had failed</b>. Y <i>while I was driving</i> (acción en curso).", next: 'f' },
            ] },
            f: { say: "You must be joking! So how did you fix it, from the car?", opts: [
              { t: "Luckily, Marco rolled it back from his laptop. If he hadn't been online, I would have had to go to the office in my empanada apron.", ok: 2, why: "Tercer condicional impecable: <b>If he hadn't been…, I would have had to…</b>. Y un cierre con humor.", next: 'win' },
              { t: "Marco rolled it back from his laptop. If he hadn't been online, I'd have gone to the office.", ok: 1, why: "Correcta: <b>if he hadn't been…, I'd have gone</b>. Natural y breve.", next: 'win' },
              { t: "Marco rolled it back. If he wouldn't have been online, I would had to go to the office.", ok: 0, why: "Dos errores típicos: <s>if he wouldn't have been</s> → <b>if he hadn't been</b>; <s>would had</s> → <b>would have had</b>.", next: 'meh' },
            ] },
            win: { say: "Ha! That's the best story I've heard all week. Anyway, lunch? I'm paying. You've suffered enough.", end: true, outcome: 'win', note: 'Contaste la historia como un nativo: gancho (<b>You won\'t believe this</b>), tensión (<b>Are you ready for this? · But that\'s not all!</b>), ironía (<b>Wouldn\'t you know it?</b>), responsabilidad (<b>my fault · should have</b>) y un tercer condicional limpio. Dani cerró con <b>Anyway</b>, como manda la unidad.' },
            meh: { say: "OK, OK, I get the idea. Anyway, lunch? I'm paying.", end: true, outcome: 'meh', note: 'La historia enganchó, pero el remate falló: en el tercer condicional nunca va <i>would</i> con <i>if</i> (<b>If he hadn\'t been online</b>) y después de <i>would</i> va <b>have</b> (<b>would have had to</b>). Dani lo pasó por alto; el examen no.' },
            fail: { say: "Come on, man. Anyway, I have to run. Tell me the rest some other time.", end: true, outcome: 'fail', note: 'Culpar a la clienta dos veces mató la historia. La unidad te da las fórmulas para reconocer un error sin hundirte: <b>It was (partly) my fault</b>, <b>there was a mix-up</b>, <b>I should have double-checked</b>. Y recuerda: <b>If she had written</b>, nunca <i>if she would have</i>.' },
          } },
        ] },
      ] },
    ],
  };
})();
